-- Approved multi-source passage corpus.
-- Existing rows are archived rather than deleted so journal references remain valid.

alter table public.quotes
  add column if not exists content_type text not null default 'direct_quote',
  add column if not exists source_work text,
  add column if not exists source_url text,
  add column if not exists translator text,
  add column if not exists rights_basis text,
  add column if not exists archived_at timestamptz;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'quotes_content_type_check'
      and conrelid = 'public.quotes'::regclass
  ) then
    alter table public.quotes
      add constraint quotes_content_type_check
      check (content_type in ('direct_quote', 'paraphrase', 'source_based_reflection'));
  end if;
end
$$;

create index if not exists idx_quotes_active_guide_created
  on public.quotes (guide_id, created_at desc, id desc)
  where archived_at is null;

update public.quotes
set archived_at = coalesce(archived_at, now());

on conflict (id) do update
set
  guide_id = excluded.guide_id,
  text = excluded.text,
  citation = excluded.citation,
  themes = excluded.themes,
  mood_tags = excluded.mood_tags,
  content_type = excluded.content_type,
  source_work = excluded.source_work,
  source_url = excluded.source_url,
  translator = excluded.translator,
  rights_basis = excluded.rights_basis,
  archived_at = null;

