insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('546d98af-1b06-4117-a998-358bad96c996', (select id from public.guides where slug = 'buddha'), 'For hatred does not cease by hatred at any time: hatred ceases by love, this is an old rule.', 'Dhammapada 5', array['forgiveness', 'love', 'support']::text[], array['angry', 'frustrated', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('4a1c7460-32f4-49ae-8636-118c32f6530c', (select id from public.guides where slug = 'buddha'), 'All that we are is the result of what we have thought: it is founded on our thoughts, it is made up of our thoughts. If a man speaks or acts with an evil thought, pain follows him, as the wheel follows the foot of the ox that draws the carriage.', 'Dhammapada 1', array['action', 'purpose', 'healing', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'grieving', 'low', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('2fbb06e2-7075-4570-b742-b45432815977', (select id from public.guides where slug = 'buddha'), 'All that we are is the result of what we have thought: it is founded on our thoughts, it is made up of our thoughts. If a man speaks or acts with a pure thought, happiness follows him, like a shadow that never leaves him.', 'Dhammapada 2', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('53a2508e-b9cb-4b32-8f3d-bf8dac1e0020', (select id from public.guides where slug = 'buddha'), 'The world does not know that we must all come to an end here;--but those who know it, their quarrels cease at once.', 'Dhammapada 6', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('4e299142-a4ae-40e1-8de6-dca1cd3afe71', (select id from public.guides where slug = 'buddha'), 'But he who has cleansed himself from sin, is well grounded in all virtues, and regards also temperance and truth, he is indeed worthy of the yellow dress.', 'Dhammapada 10', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('42ac2c0f-bbe1-433b-8e19-2d4f951faa36', (select id from public.guides where slug = 'buddha'), 'Earnestness is the path of immortality (Nirvana), thoughtlessness the path of death. Those who are in earnest do not die, those who are thoughtless are as if dead already.', 'Dhammapada 21', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('7a28e500-e35c-4165-a655-09d5c144b7cf', (select id from public.guides where slug = 'buddha'), 'By rousing himself, by earnestness, by restraint and control, the wise man may make for himself an island which no flood can overwhelm.', 'Dhammapada 25', array['discipline', 'practice']::text[], array['unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ee4d11d0-340f-4f38-aca6-3b878373ecab', (select id from public.guides where slug = 'buddha'), 'A Bhikshu (mendicant) who delights in reflection, who looks with fear on thoughtlessness, cannot fall away (from his perfect state)--he is close upon Nirvana.', 'Dhammapada 32', array['resilience', 'clarity', 'perspective', 'hope']::text[], array['fearful', 'insecure', 'confused', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('bf20a6c1-46ee-47b2-bcf0-8f40afb2b27b', (select id from public.guides where slug = 'buddha'), 'Those who are advanced in earnestness, having understood this clearly, delight in earnestness, and rejoice in the knowledge of the Ariyas (the elect).', 'Dhammapada 22', array['clarity', 'perspective', 'presence', 'hope']::text[], array['confused', 'overwhelmed', 'anxious', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('bc4bbf95-6c89-48bf-8088-78e93137caef', (select id from public.guides where slug = 'buddha'), 'If an earnest person has roused himself, if he is not forgetful, if his deeds are pure, if he acts with consideration, if he restrains himself, and lives according to law,--then his glory will increase.', 'Dhammapada 24', array['action', 'purpose', 'discipline', 'practice']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('0ed87b1e-200a-4650-97a9-48ebb7ca4bdd', (select id from public.guides where slug = 'buddha'), 'It is good to tame the mind, which is difficult to hold in and flighty, rushing wherever it listeth; a tamed mind brings happiness.', 'Dhammapada 35', array['clarity', 'perspective', 'hope']::text[], array['confused', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('6a83aae4-6658-4c18-ad4e-9c322f121e76', (select id from public.guides where slug = 'buddha'), 'If a man''s thoughts are unsteady, if he does not know the true law, if his peace of mind is troubled, his knowledge will never be perfect.', 'Dhammapada 38', array['peace', 'clarity', 'perspective', 'presence']::text[], array['anxious', 'restless', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('b995a33f-5faa-42dc-ab44-1c85b81b7de2', (select id from public.guides where slug = 'buddha'), 'If a man''s thoughts are not dissipated, if his mind is not perplexed, if he has ceased to think of good or evil, then there is no fear for him while he is watchful.', 'Dhammapada 39', array['resilience', 'clarity', 'perspective']::text[], array['fearful', 'insecure', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ac7966f1-d8e5-4609-9694-e61fa93f0d2c', (select id from public.guides where slug = 'buddha'), 'Those who bridle their mind which travels far, moves about alone, is without a body, and hides in the chamber (of the heart), will be free from the bonds of Mara (the tempter).', 'Dhammapada 37', array['clarity', 'perspective', 'love', 'support', 'connection']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('2456bb6a-f71e-4cc7-aefe-13980a46c346', (select id from public.guides where slug = 'buddha'), 'Knowing that this body is (fragile) like a jar, and making this thought firm like a fortress, one should attack Mara (the tempter) with the weapon of knowledge, one should watch him when conquered, and should never rest.', 'Dhammapada 40', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('684f23dc-73f1-4f65-9786-191f08f9678a', (select id from public.guides where slug = 'buddha'), 'Not the perversities of others, not their sins of commission or omission, but his own misdeeds and negligences should a sage take notice of.', 'Dhammapada 50', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('2965fee1-5059-4344-85eb-6e7bbe941f7d', (select id from public.guides where slug = 'buddha'), 'As many kinds of wreaths can be made from a heap of flowers, so many good things may be achieved by a mortal when once he is born.', 'Dhammapada 53', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('d4a7123b-7ef5-44ee-b36d-ef24971f93f0', (select id from public.guides where slug = 'buddha'), 'Death carries off a man who is gathering flowers and whose mind is distracted, as a flood carries off a sleeping village.', 'Dhammapada 47', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9ce241fd-1ce4-46f2-9b53-8d8ff4927f17', (select id from public.guides where slug = 'buddha'), 'Death subdues a man who is gathering flowers, and whose mind is distracted, before he is satiated in his pleasures.', 'Dhammapada 48', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('69c08ebc-d6e2-4d4b-8fde-fbe7c5fd27a2', (select id from public.guides where slug = 'buddha'), 'If a traveller does not meet with one who is his better, or his equal, let him firmly keep to his solitary journey; there is no companionship with a fool.', 'Dhammapada 61', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('6ed01f80-433b-468b-83ec-93416fa4262e', (select id from public.guides where slug = 'buddha'), 'If a fool be associated with a wise man even all his life, he will perceive the truth as little as a spoon perceives the taste of soup.', 'Dhammapada 64', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c03cc21a-e1fc-469d-a6cb-95ad42f17bf7', (select id from public.guides where slug = 'buddha'), '"May both the layman and he who has left the world think that this is done by me; may they be subject to me in everything which is to be done or is not to be done," thus is the mind of the fool, and his desire and pride increase.', 'Dhammapada 74', array['clarity', 'perspective', 'detachment']::text[], array['confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('93d8491e-773b-435b-a734-70f905facf2f', (select id from public.guides where slug = 'buddha'), 'Long is the night to him who is awake; long is a mile to him who is tired; long is life to the foolish who do not know the true law.', 'Dhammapada 60', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('7b7f1c03-ef18-4674-9cca-39fb91f73c9c', (select id from public.guides where slug = 'buddha'), 'Well-makers lead the water (wherever they like); fletchers bend the arrow; carpenters bend a log of wood; wise people fashion themselves.', 'Dhammapada 80', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9b942e2a-3d39-4ef5-97d6-d9b569baf96a', (select id from public.guides where slug = 'buddha'), 'As a solid rock is not shaken by the wind, wise people falter not amidst blame and praise.', 'Dhammapada 81', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('1253a02b-ffad-4d9f-a9e7-11973cf6bb9b', (select id from public.guides where slug = 'buddha'), 'Those whose mind is well grounded in the (seven) elements of knowledge, who without clinging to anything, rejoice in freedom from attachment, whose appetites have been conquered, and who are full of light, are free (even) in this world.', 'Dhammapada 89', array['clarity', 'perspective', 'presence', 'detachment', 'hope']::text[], array['confused', 'overwhelmed', 'anxious', 'discontent', 'restless', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('0bc723e8-dfbe-404f-9e71-a26e343df340', (select id from public.guides where slug = 'buddha'), 'Let him admonish, let him teach, let him forbid what is improper!--he will be beloved of the good, by the bad he will be hated.', 'Dhammapada 77', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('71cea398-b15b-4d46-89e6-4d2e442675c8', (select id from public.guides where slug = 'buddha'), 'Good people walk on whatever befall, the good do not prattle, longing for pleasure; whether touched by happiness or sorrow wise people never appear elated or depressed.', 'Dhammapada 83', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('448134fe-7307-44d6-994a-0e6b75b69d78', (select id from public.guides where slug = 'buddha'), 'His thought is quiet, quiet are his word and deed, when he has obtained freedom by true knowledge, when he has thus become a quiet man.', 'Dhammapada 96', array['peace', 'clarity', 'perspective', 'presence']::text[], array['anxious', 'restless', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('23452dc1-3607-4aa1-83e4-42df0137ed28', (select id from public.guides where slug = 'buddha'), 'There is no suffering for him who has finished his journey, and abandoned grief, who has freed himself on all sides, and thrown off all fetters.', 'Dhammapada 90', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9063d3a7-07d2-4958-a4c1-71341e2f84ac', (select id from public.guides where slug = 'buddha'), 'Men who have no riches, who live on recognised food, who have perceived void and unconditioned freedom (Nirvana), their path is difficult to understand, like that of birds in the air.', 'Dhammapada 92', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ecf226df-e9cb-4a80-b76f-c58a5ac1f092', (select id from public.guides where slug = 'buddha'), 'He whose appetites are stilled, who is not absorbed in enjoyment, who has perceived void and unconditioned freedom (Nirvana), his path is difficult to understand, like that of birds in the air.', 'Dhammapada 93', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9af7b221-1a7a-4ad5-992d-ed2882fdd5e2', (select id from public.guides where slug = 'buddha'), 'Even though a speech be a thousand (of words), but made up of senseless words, one word of sense is better, which if a man hears, he becomes quiet.', 'Dhammapada 100', array['peace']::text[], array['anxious', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('fe391d7f-9edd-49f0-95da-b92a407c8864', (select id from public.guides where slug = 'buddha'), 'If one man conquer in battle a thousand times thousand men, and if another conquer himself, he is the greatest of conquerors. 104, 105. One''s own self conquered is better than all other people; not even a god, a Gandharva, not Mara with Brahman could change into defeat the victory of a man who has vanquished himself, and always lives under restraint.', 'Dhammapada 103', array['impermanence', 'acceptance', 'discipline', 'practice']::text[], array['grieving', 'fearful', 'unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('597f9932-11d8-4a14-a130-3de7c8b95a3a', (select id from public.guides where slug = 'buddha'), 'But he who lives a hundred years, vicious and unrestrained, a life of one day is better if a man is virtuous and reflecting.', 'Dhammapada 110', array['discipline', 'practice']::text[], array['unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('2d07d8ee-065e-448d-882a-4860a1b59700', (select id from public.guides where slug = 'buddha'), 'And he who lives a hundred years, ignorant and unrestrained, a life of one day is better if a man is wise and reflecting.', 'Dhammapada 111', array['discipline', 'practice']::text[], array['unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('8060cba1-a15a-4d0d-9724-8a9aadef3419', (select id from public.guides where slug = 'buddha'), 'If a man would hasten towards the good, he should keep his thought away from evil; if a man does what is good slothfully, his mind delights in evil.', 'Dhammapada 116', array['clarity', 'perspective', 'hope']::text[], array['confused', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ab2bf255-4758-4bc1-a30d-e106dfcd58b7', (select id from public.guides where slug = 'buddha'), 'Let no man think lightly of good, saying in his heart, It will not come nigh unto me. Even by the falling of water-drops a water-pot is filled; the wise man becomes full of good, even if he gather it little by little.', 'Dhammapada 122', array['love', 'support', 'hope']::text[], array['guilty', 'tired', 'low']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c58fb5ed-2fe1-49c5-9ddf-81a7856d148c', (select id from public.guides where slug = 'buddha'), 'Let a man avoid evil deeds, as a merchant, if he has few companions and carries much wealth, avoids a dangerous road; as a man who loves life avoids poison.', 'Dhammapada 123', array['forgiveness', 'love', 'support']::text[], array['angry', 'frustrated', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('f32baaed-a58e-479b-a293-f84938b9a5f9', (select id from public.guides where slug = 'buddha'), 'If a man does what is good, let him do it again; let him delight in it: happiness is the outcome of good.', 'Dhammapada 118', array['hope']::text[], array['low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('6cde4739-bc8e-4529-9bfb-c187a53a5f0c', (select id from public.guides where slug = 'buddha'), 'Do not speak harshly to anybody; those who are spoken to will answer thee in the same way. Angry speech is painful, blows for blows will touch thee.', 'Dhammapada 133', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('602886b0-57bb-4217-b27a-a65f01982ce7', (select id from public.guides where slug = 'buddha'), 'All men tremble at punishment, all men love life; remember that thou art like unto them, and do not kill, nor cause slaughter.', 'Dhammapada 130', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('81372e7a-fa55-4df1-9f17-c34cd863cf84', (select id from public.guides where slug = 'buddha'), 'All men tremble at punishment, all men fear death; remember that you are like unto them, and do not kill, nor cause slaughter.', 'Dhammapada 129', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('6c73f251-065f-4990-b07f-2dc3f117e0b9', (select id from public.guides where slug = 'buddha'), 'If, like a shattered metal plate (gong), thou utter not, then thou hast reached Nirvana; contention is not known to thee.', 'Dhammapada 134', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c38885d5-b99d-4414-b6e7-9ce63800d653', (select id from public.guides where slug = 'buddha'), 'As a cowherd with his staff drives his cows into the stable, so do Age and Death drive the life of men.', 'Dhammapada 135', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('6a888b2d-3fb7-41a8-a704-107b13472aec', (select id from public.guides where slug = 'buddha'), 'This body is wasted, full of sickness, and frail; this heap of corruption breaks to pieces, life indeed ends in death.', 'Dhammapada 148', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ca807c0d-5b58-4546-804d-d320ac761086', (select id from public.guides where slug = 'buddha'), 'The brilliant chariots of kings are destroyed, the body also approaches destruction, but the virtue of good people never approaches destruction,--thus do the good say to the good.', 'Dhammapada 151', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9b0885ea-56a6-482f-8629-bec5b53bbc63', (select id from public.guides where slug = 'buddha'), 'Men who have not observed proper discipline, and have not gained treasure in their youth, perish like old herons in a lake without fish.', 'Dhammapada 155', array['discipline', 'practice']::text[], array['unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('8fa5c442-d342-46d6-bfa4-a1f82c65e5fa', (select id from public.guides where slug = 'buddha'), 'Men who have not observed proper discipline, and have not gained treasure in their youth, lie, like broken bows, sighing after the past.', 'Dhammapada 156', array['discipline', 'practice']::text[], array['unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ef74a3dc-6170-43aa-af19-7a147cb94120', (select id from public.guides where slug = 'buddha'), 'Self is the lord of self, who else could be the lord? With self well subdued, a man finds a lord such as few can find.', 'Dhammapada 160', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('2d74ad00-8a5e-4e14-8c5c-d6a1c978f024', (select id from public.guides where slug = 'buddha'), 'By oneself the evil is done, by oneself one suffers; by oneself evil is left undone, by oneself one is purified. Purity and impurity belong to oneself, no one can purify another.', 'Dhammapada 165', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('7fa4e690-69a5-4f68-baf5-c65b424b1c10', (select id from public.guides where slug = 'buddha'), 'If a man hold himself dear, let him watch himself carefully; during one at least out of the three watches a wise man should be watchful.', 'Dhammapada 157', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('167ab905-2df0-48b4-a1f8-81cbf3f9e3f1', (select id from public.guides where slug = 'buddha'), 'Let each man direct himself first to what is proper, then let him teach others; thus a wise man will not suffer.', 'Dhammapada 158', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('e1ed613a-0d8b-4c38-bed3-b2b28712ba61', (select id from public.guides where slug = 'buddha'), 'If a man make himself as he teaches others to be, then, being himself well subdued, he may subdue (others); one''s own self is indeed difficult to subdue.', 'Dhammapada 159', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('0d288dd2-c718-487f-bdfd-47fce0b2a93d', (select id from public.guides where slug = 'buddha'), 'Do not follow the evil law! Do not live on in thoughtlessness! Do not follow false doctrine! Be not a friend of the world.', 'Dhammapada 167', array['clarity', 'perspective', 'love', 'support']::text[], array['confused', 'overwhelmed', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('05a09079-bf1b-4558-8126-a581d502b1bc', (select id from public.guides where slug = 'buddha'), 'Rouse thyself! do not be idle! Follow the law of virtue! The virtuous rests in bliss in this world and in the next.', 'Dhammapada 168', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('cb777e99-1e41-4abf-a398-1e5f8931b55e', (select id from public.guides where slug = 'buddha'), 'He whose evil deeds are covered by good deeds, brightens up this world, like the moon when freed from clouds.', 'Dhammapada 173', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('0badf1c5-9f9a-4fef-a491-1f5a2076e0c7', (select id from public.guides where slug = 'buddha'), 'Follow the law of virtue; do not follow that of sin. The virtuous rests in bliss in this world and in the next.', 'Dhammapada 169', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('f6d3f94d-a770-41f0-b227-169c00ba281c', (select id from public.guides where slug = 'buddha'), 'Not to commit any sin, to do good, and to purify one''s mind, that is the teaching of (all) the Awakened.', 'Dhammapada 183', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('b61b990b-75b0-471c-8acb-3acb1b2d5551', (select id from public.guides where slug = 'buddha'), 'Even in heavenly pleasures he finds no satisfaction, the disciple who is fully awakened delights only in the destruction of all desires.', 'Dhammapada 187', array['action', 'purpose', 'detachment', 'hope']::text[], array['stuck', 'unmotivated', 'discontent', 'restless', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ea720a41-08c5-4f44-b602-69968be98568', (select id from public.guides where slug = 'buddha'), 'Difficult (to obtain) is the conception of men, difficult is the life of mortals, difficult is the hearing of the True Law, difficult is the birth of the Awakened (the attainment of Buddhahood).', 'Dhammapada 182', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('e31d1073-2dc5-40eb-ad93-7eae897b4c0d', (select id from public.guides where slug = 'buddha'), 'The Awakened call patience the highest penance, long-suffering the highest Nirvana; for he is not an anchorite (pravragita) who strikes others, he is not an ascetic (sramana) who insults others.', 'Dhammapada 184', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('768a744d-f8bd-433c-ab5a-e7d47afce023', (select id from public.guides where slug = 'buddha'), 'Let us live happily then, not hating those who hate us! among men who hate us let us dwell free from hatred!', 'Dhammapada 197', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('f14e7ca5-ad0a-46e2-b3d6-ae737b21774f', (select id from public.guides where slug = 'buddha'), 'Victory breeds hatred, for the conquered is unhappy. He who has given up both victory and defeat, he, the contented, is happy.', 'Dhammapada 201', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('e801627c-2ce6-45ae-b4dd-3ec2248b6024', (select id from public.guides where slug = 'buddha'), 'Health is the greatest of gifts, contentedness the best riches; trust is the best of relationships, Nirvana the highest happiness.', 'Dhammapada 204', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('a88ac4a7-60b7-4818-bb07-ca82177bd96f', (select id from public.guides where slug = 'buddha'), 'He who has tasted the sweetness of solitude and tranquillity, is free from fear and free from sin, while he tastes the sweetness of drinking in the law.', 'Dhammapada 205', array['peace', 'resilience']::text[], array['anxious', 'restless', 'fearful', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c750b165-dd21-4026-92b8-970b72e17283', (select id from public.guides where slug = 'buddha'), 'From love comes grief, from love comes fear; he who is free from love knows neither grief nor fear.', 'Dhammapada 215', array['resilience', 'healing', 'clarity', 'perspective', 'love', 'support', 'presence']::text[], array['fearful', 'insecure', 'grieving', 'low', 'confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('600b1f5c-d746-46c9-a1c6-03076d189ccf', (select id from public.guides where slug = 'buddha'), 'He in whom a desire for the Ineffable (Nirvana) has sprung up, who is satisfied in his mind, and whose thoughts are not bewildered by love, he is called urdhvamsrotas (carried upwards by the stream).', 'Dhammapada 218', array['clarity', 'perspective', 'love', 'support', 'detachment']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'discontent', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('39baa27d-ff6f-4cd0-a90d-80dc254c5ccd', (select id from public.guides where slug = 'buddha'), 'In like manner his good works receive him who has done good, and has gone from this world to the other;--as kinsmen receive a friend on his return.', 'Dhammapada 220', array['action', 'purpose', 'love', 'support']::text[], array['stuck', 'unmotivated', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('caf8027c-aaa2-4849-8b89-d778e62b7aee', (select id from public.guides where slug = 'buddha'), 'He who gives himself to vanity, and does not give himself to meditation, forgetting the real aim (of life) and grasping at pleasure, will in time envy him who has exerted himself in meditation.', 'Dhammapada 209', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('3a62d768-8c85-4283-ba0b-4a28ec2df71d', (select id from public.guides where slug = 'buddha'), 'Let a man overcome anger by love, let him overcome evil by good; let him overcome the greedy by liberality, the liar by truth!', 'Dhammapada 223', array['forgiveness', 'clarity', 'perspective', 'love', 'support']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('52319bbf-73f7-4e12-8325-15cba7096105', (select id from public.guides where slug = 'buddha'), 'Let a man leave anger, let him forsake pride, let him overcome all bondage! No sufferings befall the man who is not attached to name and form, and who calls nothing his own.', 'Dhammapada 221', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('0d75c67f-7033-4920-861a-0f8d09016474', (select id from public.guides where slug = 'buddha'), 'The sages who injure nobody, and who always control their body, they will go to the unchangeable place (Nirvana), where, if they have gone, they will suffer no more.', 'Dhammapada 225', array['impermanence', 'acceptance', 'discipline', 'practice']::text[], array['grieving', 'fearful', 'unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('cb834554-18ce-42af-968e-a46a27745e1c', (select id from public.guides where slug = 'buddha'), 'The wise who control their body, who control their tongue, the wise who control their mind, are indeed well controlled.', 'Dhammapada 234', array['clarity', 'perspective', 'discipline', 'practice']::text[], array['confused', 'overwhelmed', 'unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c1b306c6-762d-437c-9547-88b28027014d', (select id from public.guides where slug = 'buddha'), 'Make thyself an island, work hard, be wise! When thy impurities are blown away, and thou art free from guilt, thou wilt enter into the heavenly world of the elect (Ariya).', 'Dhammapada 236', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('0a5ba1d0-6865-44eb-814f-c6a2f55b61a6', (select id from public.guides where slug = 'buddha'), 'Make thyself an island, work hard, be wise! When thy impurities are blown away, and thou art free from guilt, thou wilt not enter again into birth and decay.', 'Dhammapada 238', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('69e0f5d0-efb7-4861-8984-22bddfd660dc', (select id from public.guides where slug = 'buddha'), 'But life is hard to live for a modest man, who always looks for what is pure, who is disinterested, quiet, spotless, and intelligent.', 'Dhammapada 245', array['peace']::text[], array['anxious', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('4539d311-9cec-440d-bdfd-d43d35a3e88d', (select id from public.guides where slug = 'buddha'), 'He who destroys life, who speaks untruth, who in this world takes what is not given him, who goes to another man''s wife;', 'Dhammapada 246', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('f094d127-8c3c-403b-8328-3649f1457d23', (select id from public.guides where slug = 'buddha'), 'He in whom there is truth, virtue, love, restraint, moderation, he who is free from impurity and is wise, he is called an elder.', 'Dhammapada 261', array['clarity', 'perspective', 'love', 'support', 'discipline', 'practice']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9d77c5e9-ea72-4321-9cce-c2946e02c82d', (select id from public.guides where slug = 'buddha'), 'Not by tonsure does an undisciplined man who speaks falsehood become a Samana; can a man be a Samana who is still held captive by desire and greediness?', 'Dhammapada 264', array['detachment', 'discipline', 'practice']::text[], array['discontent', 'restless', 'unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('1e0fc71e-e598-4801-aa1b-106899731d33', (select id from public.guides where slug = 'buddha'), 'A man is not learned because he talks much; he who is patient, free from hatred and fear, he is called learned.', 'Dhammapada 258', array['forgiveness', 'resilience']::text[], array['angry', 'frustrated', 'fearful', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('5f569d7c-e5ce-4712-9cc1-f2c265b92356', (select id from public.guides where slug = 'buddha'), 'He who always quiets the evil, whether small or large, he is called a Samana (a quiet man), because he has quieted all evil.', 'Dhammapada 265', array['peace']::text[], array['anxious', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('fec72716-f8fc-4f84-9574-5ffe6f40ce6e', (select id from public.guides where slug = 'buddha'), 'You yourself must make an effort. The Tathagatas (Buddhas) are only preachers. The thoughtful who enter the way are freed from the bondage of Mara.', 'Dhammapada 276', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('8f4646f2-8a2f-4b9d-b73a-197442eab098', (select id from public.guides where slug = 'buddha'), 'Cut out the love of self, like an autumn lotus, with thy hand! Cherish the road of peace. Nirvana has been shown by Sugata (Buddha).', 'Dhammapada 285', array['peace', 'love', 'support']::text[], array['anxious', 'restless', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('e91edd09-5e4b-4baf-9aa9-4e2b0ff631b2', (select id from public.guides where slug = 'buddha'), 'He who does not rouse himself when it is time to rise, who, though young and strong, is full of sloth, whose will and thought are weak, that lazy and idle man will never find the way to knowledge.', 'Dhammapada 280', array['clarity', 'perspective', 'presence', 'hope']::text[], array['confused', 'overwhelmed', 'anxious', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('8c9315ca-6464-45e5-9af9-16eae636c2dc', (select id from public.guides where slug = 'buddha'), 'Watching his speech, well restrained in mind, let a man never commit any wrong with his body! Let a man but keep these three roads of action clear, and he will achieve the way which is taught by the wise.', 'Dhammapada 281', array['action', 'purpose', 'clarity', 'perspective', 'discipline', 'practice']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c2e78d97-63b0-4cb5-ad7e-3237f834bf84', (select id from public.guides where slug = 'buddha'), 'He alone who, without ceasing, practises the duty of sitting alone and sleeping alone, he, subduing himself, will rejoice in the destruction of all desires alone, as if living in a forest.', 'Dhammapada 305', array['action', 'purpose', 'detachment', 'connection', 'support']::text[], array['stuck', 'unmotivated', 'discontent', 'restless', 'low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('561fa9f3-e583-48eb-8100-bbbd381524f8', (select id from public.guides where slug = 'buddha'), 'The disciples of Gotama are always well awake, and their mind day and night always delights in compassion.', 'Dhammapada 300', array['clarity', 'perspective', 'love', 'support', 'hope']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'low']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('5a96082e-39e4-423f-ba37-18026a6af568', (select id from public.guides where slug = 'buddha'), 'He who, by causing pain to others, wishes to obtain pleasure for himself, he, entangled in the bonds of hatred, will never be free from hatred.', 'Dhammapada 291', array['forgiveness', 'healing', 'connection', 'support']::text[], array['angry', 'frustrated', 'grieving', 'low', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('a40aac19-87dc-45e2-bd3b-a764377dbb68', (select id from public.guides where slug = 'buddha'), 'What ought to be done is neglected, what ought not to be done is done; the desires of unruly, thoughtless people are always increasing.', 'Dhammapada 292', array['clarity', 'perspective', 'detachment']::text[], array['confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ef72b7fe-62f2-4f8c-b375-d102bf9eeea4', (select id from public.guides where slug = 'buddha'), 'An act carelessly performed, a broken vow, and hesitating obedience to discipline, all this brings no great reward.', 'Dhammapada 312', array['action', 'purpose', 'discipline', 'practice']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('9447e8bb-b022-48dd-8867-c66f1d2472a2', (select id from public.guides where slug = 'buddha'), 'An evil deed is better left undone, for a man repents of it afterwards; a good deed is better done, for having done it, one does not repent.', 'Dhammapada 314', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c6d7d34f-39b5-4e48-a4f8-3d0400d69b73', (select id from public.guides where slug = 'buddha'), 'They who fear when they ought not to fear, and fear not when they ought to fear, such men, embracing false doctrines, enter the evil path.', 'Dhammapada 317', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('31bcedb2-f0f4-4e69-9423-2154884549aa', (select id from public.guides where slug = 'buddha'), 'They who know what is forbidden as forbidden, and what is not forbidden as not forbidden, such men, embracing the true doctrine, enter the good path.', 'Dhammapada 319', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('59e08c79-7a99-4d00-bf80-1cbbc5689b5d', (select id from public.guides where slug = 'buddha'), 'Silently shall I endure abuse as the elephant in battle endures the arrow sent from the bow: for the world is ill-natured.', 'Dhammapada 320', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('cd0b428b-3544-4a8f-9f13-754f67aba123', (select id from public.guides where slug = 'buddha'), 'If a man find a prudent companion who walks with him, is wise, and lives soberly, he may walk with him, overcoming all dangers, happy, but considerate.', 'Dhammapada 328', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('0b68675e-155e-42ad-a58d-bc3b90d0b58a', (select id from public.guides where slug = 'buddha'), 'If an occasion arises, friends are pleasant; enjoyment is pleasant, whatever be the cause; a good work is pleasant in the hour of death; the giving up of all grief is pleasant.', 'Dhammapada 331', array['action', 'purpose', 'healing', 'love', 'support', 'hope']::text[], array['stuck', 'unmotivated', 'grieving', 'low', 'guilty', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('c112c5a8-1902-4951-b6f3-6427c94454eb', (select id from public.guides where slug = 'buddha'), 'Mules are good, if tamed, and noble Sindhu horses, and elephants with large tusks; but he who tames himself is better still.', 'Dhammapada 322', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('d63f459f-f2a7-4e04-95e0-fb9d9c2546f0', (select id from public.guides where slug = 'buddha'), 'The gift of the law exceeds all gifts; the sweetness of the law exceeds all sweetness; the delight in the law exceeds all delights; the extinction of thirst overcomes all pain.', 'Dhammapada 354', array['healing', 'hope']::text[], array['grieving', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('2b5c5b29-bb6a-442a-9f75-3d515cf5996e', (select id from public.guides where slug = 'buddha'), 'Those who are slaves to passions, run down with the stream (of desires), as a spider runs down the web which he has made himself; when they have cut this, at last, wise people leave the world free from cares, leaving all affection behind.', 'Dhammapada 347', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('37ee2c78-571c-40a3-b8ad-b4f279e8e351', (select id from public.guides where slug = 'buddha'), 'If a man delights in quieting doubts, and, always reflecting, dwells on what is not delightful (the impurity of the body, &c.), he certainly will remove, nay, he will cut the fetter of Mara.', 'Dhammapada 350', array['peace', 'hope']::text[], array['anxious', 'restless', 'low', 'tired']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('6bfdd1f5-6deb-4282-aa1e-9fa851e27e3d', (select id from public.guides where slug = 'buddha'), '`I have conquered all, I know all, in all conditions of life I am free from taint; I have left all, and through the destruction of thirst I am free; having learnt myself, whom shall I teach?''', 'Dhammapada 353', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('976c1714-26b6-4223-9cac-7cffcb8bca06', (select id from public.guides where slug = 'buddha'), 'Without knowledge there is no meditation, without meditation there is no knowledge: he who has knowledge and meditation is near unto Nirvana.', 'Dhammapada 372', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('79d85de3-a14f-4300-864d-b4f600dd824d', (select id from public.guides where slug = 'buddha'), 'Rouse thyself by thyself, examine thyself by thyself, thus self-protected and attentive wilt thou live happily, O Bhikshu!', 'Dhammapada 379', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('f9dedd21-e6b5-47c0-879c-737a275d0d67', (select id from public.guides where slug = 'buddha'), 'The Bhikshu who acts with kindness, who is calm in the doctrine of Buddha, will reach the quiet place (Nirvana), cessation of natural desires, and happiness.', 'Dhammapada 368', array['peace', 'action', 'purpose', 'detachment']::text[], array['anxious', 'restless', 'stuck', 'unmotivated', 'discontent']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('8c189949-bcae-4831-a7a4-b13cda18f204', (select id from public.guides where slug = 'buddha'), 'And this is the beginning here for a wise Bhikshu: watchfulness over the senses, contentedness, restraint under the law; keep noble friends whose life is pure, and who are not slothful.', 'Dhammapada 375', array['love', 'support', 'discipline', 'practice']::text[], array['guilty', 'tired', 'unmotivated', 'stuck']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('3d07fbdf-1bf8-44ff-b217-ebb32874ff69', (select id from public.guides where slug = 'buddha'), 'Him I call indeed a Brahmana who is tolerant with the intolerant, mild with fault-finders, and free from passion among the passionate.', 'Dhammapada 406', array['peace']::text[], array['anxious']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('22addba3-3ec5-4174-a22e-92ba3e5da227', (select id from public.guides where slug = 'buddha'), 'It advantages a Brahmana not a little if he holds his mind back from the pleasures of life; when all wish to injure has vanished, pain will cease.', 'Dhammapada 390', array['healing', 'clarity', 'perspective', 'impermanence', 'acceptance']::text[], array['grieving', 'low', 'confused', 'overwhelmed', 'fearful']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('fc503441-5050-4262-88a5-cee51aadbe8e', (select id from public.guides where slug = 'buddha'), 'Him I call indeed a Brahmana who, though he has committed no offence, endures reproach, bonds, and stripes, who has endurance for his force, and strength for his army.', 'Dhammapada 399', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('ba31fb3c-bd01-40cc-bcfc-95e0645c1b94', (select id from public.guides where slug = 'buddha'), 'Him I call indeed a Brahmana whose knowledge is deep, who possesses wisdom, who knows the right way and the wrong, and has attained the highest end.', 'Dhammapada 403', array['clarity', 'perspective', 'presence', 'detachment']::text[], array['confused', 'overwhelmed', 'anxious', 'discontent', 'restless']::text[], 'direct_quote', 'The Dhammapada', 'https://www.gutenberg.org/cache/epub/2017/pg2017.txt', 'F. Max Muller', 'Public domain in the USA; F. Max Muller translation, 1881', null),
  ('a7aaebb9-d4df-4fd9-9454-bbb4dba26b14', (select id from public.guides where slug = 'bhagavad-gita'), 'For I desire to observe those who are assembled here for fight, wishing to please the evil-minded Duryodhana by taking his side on this battle-field.', 'Bhagavad Gita 1.23', array['clarity', 'perspective', 'detachment']::text[], array['confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg06.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('ec1369a9-1fe7-4daa-b33d-7ab92e1f98bb', (select id from public.guides where slug = 'bhagavad-gita'), 'Then he, the son of Kunti, seeing all those kinsmen stationed in their ranks, spoke thus sorrowfully, filled with deep compassion.', 'Bhagavad Gita 1.27', array['healing', 'love', 'support']::text[], array['grieving', 'low', 'guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg06.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('4f24ee7f-4004-48ff-8466-b3a7c1b8a42d', (select id from public.guides where slug = 'bhagavad-gita'), 'Endued with this evenness of mind, one frees oneself in this life, alike from vice and virtue. Devote thyself, therefore, to this Yoga. Yoga is the very dexterity of work.', 'Bhagavad Gita 2.50', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e0672bae-4f84-4891-992c-fccc63240832', (select id from public.guides where slug = 'bhagavad-gita'), 'He whose mind is not shaken by adversity, who does not hanker after happiness, who has become free from affection, fear, and wrath, is indeed the Muni of steady wisdom.', 'Bhagavad Gita 2.56', array['forgiveness', 'resilience', 'clarity', 'perspective']::text[], array['angry', 'frustrated', 'fearful', 'insecure', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b5f50c3f-267a-4583-8571-2fa5ec752973', (select id from public.guides where slug = 'bhagavad-gita'), 'With my nature overpowered by weak commiseration, with a mind in confusion about duty, I supplicate Thee. Say decidedly what is good for me. I am Thy disciple. Instruct me who have taken refuge in Thee.', 'Bhagavad Gita 2.7', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e7066480-7bc9-4ff6-a85c-1ad89991e7be', (select id from public.guides where slug = 'bhagavad-gita'), 'Thy right is to work only; but never to the fruits thereof. Be thou not the producer of the fruits of (thy) actions; neither let thy attachment be towards inaction.', 'Bhagavad Gita 2.47', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('95fb80fb-f40c-47cd-bb75-67e02c30286e', (select id from public.guides where slug = 'bhagavad-gita'), 'Being steadfast in Yoga, Dhananjaya, perform actions, abandoning attachment, remaining unconcerned as regards success and failure. This evenness. of mind (in regard to success and failure) is known as Yoga.', 'Bhagavad Gita 2.48', array['action', 'purpose', 'clarity', 'perspective', 'presence', 'detachment']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('50f66f95-8f59-477f-ae60-72c5ccdeaa3f', (select id from public.guides where slug = 'bhagavad-gita'), 'As into the ocean,—brimful, and still,—flow the waters, even so the Muni into whom enter all desires, he, and not the desirer of desires, attains to peace.', 'Bhagavad Gita 2.70', array['peace', 'detachment']::text[], array['anxious', 'restless', 'discontent']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('a82a20c5-35ec-463e-92df-3c97167c7b9c', (select id from public.guides where slug = 'bhagavad-gita'), 'Notions of heat and cold, of pain and pleasure, are born, O son of Kunti, only of the contact of the senses with their objects. They have a beginning and an end. They are impermanent in their nature. Bear them patiently, O descendant of Bharata.', 'Bhagavad Gita 2.14', array['action', 'purpose', 'healing', 'impermanence', 'acceptance']::text[], array['stuck', 'unmotivated', 'grieving', 'low', 'fearful']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('f77b8a9f-5105-4ae9-b283-5b5ffecb0118', (select id from public.guides where slug = 'bhagavad-gita'), 'Having made pain and pleasure, gain and loss, conquest and defeat, the same, engage thou then in battle. So shalt thou incur no sin.', 'Bhagavad Gita 2.38', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('472a6e8c-e329-4438-9380-138a8ed3c538', (select id from public.guides where slug = 'bhagavad-gita'), 'Thinking of objects, attachment to them is formed in a man. From attachment longing, and from longing anger grows.', 'Bhagavad Gita 2.62', array['forgiveness', 'detachment']::text[], array['angry', 'frustrated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b10e2e51-7da8-4755-a107-8cf03f56936a', (select id from public.guides where slug = 'bhagavad-gita'), 'From anger comes delusion, and from delusion loss of memory. From loss of memory comes the ruin of discrimination, and from the ruin of discrimination he perishes.', 'Bhagavad Gita 2.63', array['forgiveness', 'healing']::text[], array['angry', 'frustrated', 'grieving', 'low']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('cddf1ca7-d30d-40b2-a18b-1535bd1b49c5', (select id from public.guides where slug = 'bhagavad-gita'), 'This in never born, nor does It die. It is not that not having been It again comes into being. (Or according to another view: It is not that having been It again ceases to be). This is unborn, eternal, changeless, ever-Itself. It is not killed when the body is killed.', 'Bhagavad Gita 2.20', array['impermanence', 'acceptance']::text[], array['grieving', 'fearful']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('64ca4c10-db4c-48e9-865d-7ea442c727c9', (select id from public.guides where slug = 'bhagavad-gita'), 'When a man completely casts away, O Pârtha, all the desires of the mind, satisfied in the Self alone by the Self, then is he said to be one of steady wisdom.', 'Bhagavad Gita 2.55', array['clarity', 'perspective', 'detachment', 'connection', 'support']::text[], array['confused', 'overwhelmed', 'discontent', 'restless', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('627301da-45fc-4594-8c5c-1ae76d91dafd', (select id from public.guides where slug = 'bhagavad-gita'), 'Work (with desire) is verily far inferior to that performed with the mind undisturbed by thoughts of results. O [paragraph continues] Dhananjaya, seek refuge in this evenness of mind. Wretched are they who act for results.', 'Bhagavad Gita 2.49', array['action', 'purpose', 'clarity', 'perspective', 'detachment']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg07.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('eda33495-be95-44ad-b578-aed13cc4d484', (select id from public.guides where slug = 'bhagavad-gita'), 'Therefore, do thou always perform actions which are obligatory, without attachment;—by performing action without attachment, one attains to the highest.', 'Bhagavad Gita 3.19', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e6b1fee2-fb35-4b60-97d0-39014d8ff7f0', (select id from public.guides where slug = 'bhagavad-gita'), 'Better is one''s own Dharma, (though) imperfect, than the Dharma of another well-performed. Better is death in one''s own Dharma: the Dharma of another is fraught with fear.', 'Bhagavad Gita 3.35', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('88157db2-6f65-4ebc-a2a2-983d2a6692b1', (select id from public.guides where slug = 'bhagavad-gita'), 'Renouncing all actions to Me, with mind centred on the Self, getting rid of hope and selfishness, fight,—free from (mental) fever.', 'Bhagavad Gita 3.30', array['action', 'purpose', 'clarity', 'perspective', 'hope']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('6c01fe17-3311-47fe-bf0a-1fc34bf76a23', (select id from public.guides where slug = 'bhagavad-gita'), 'But, who, controlling the senses by the mind, unattached, directs his organs of action to the path of work, he, O Arjuna, excels.', 'Bhagavad Gita 3.7', array['action', 'purpose', 'clarity', 'perspective', 'discipline', 'practice']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('1f177e45-9e46-48c9-ab08-8738e0efc163', (select id from public.guides where slug = 'bhagavad-gita'), 'But the man who is devoted to the Self, and is satisfied with the Self, and content in the Self alone, he has no obligatory duty.', 'Bhagavad Gita 3.17', array['action', 'purpose', 'connection', 'support']::text[], array['stuck', 'unmotivated', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('a803bd00-0106-476e-a1d2-d529b83274fe', (select id from public.guides where slug = 'bhagavad-gita'), 'One should not unsettle the understanding of the ignorant, attached to action; the wise, (himself) steadily acting, should engage (the ignorant) in all work.', 'Bhagavad Gita 3.26', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('62c5ae0b-aeb5-40bb-bdc3-70fe4ff14377', (select id from public.guides where slug = 'bhagavad-gita'), 'The Prajâpati, having in the beginning created mankind together with Yajna, said,—"By this shall ye multiply: this shall be the milch cow of your desires.', 'Bhagavad Gita 3.10', array['detachment', 'connection', 'support']::text[], array['discontent', 'restless', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b97220fb-8d39-4ec4-b1c8-df8bee5ac73f', (select id from public.guides where slug = 'bhagavad-gita'), 'I have, O son of Prithâ, no duty, nothing that I have not gained, and nothing that I have to gain, in the three worlds; yet, I continue in action.', 'Bhagavad Gita 3.22', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('6f102528-20c0-4631-9efa-7fc415006352', (select id from public.guides where slug = 'bhagavad-gita'), 'In the beginning (of creation), O sinless one, the twofold path of devotion was given by Me to this world;—the path of knowledge for the meditative, the path of work for the active.', 'Bhagavad Gita 3.3', array['action', 'purpose', 'clarity', 'perspective', 'presence']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg08.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('1b48e35b-c608-44cb-bcda-64aa40af5ca6', (select id from public.guides where slug = 'bhagavad-gita'), 'Verily there exists nothing in this world purifying like knowledge. In good time, having reached perfection in Yoga, one realises that oneself in one''s own heart.', 'Bhagavad Gita 4.38', array['clarity', 'perspective', 'love', 'support', 'presence']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b3960fd8-77e3-4e6e-8ebb-41b5936d9c66', (select id from public.guides where slug = 'bhagavad-gita'), 'In whatever way men worship Me, in the same way do I fulfil their desires: (it is) My path, O son of Prithâ, (that) men tread, in all ways.', 'Bhagavad Gita 4.11', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e521c848-81e3-4677-b2eb-531873566897', (select id from public.guides where slug = 'bhagavad-gita'), 'Whenever, O descendant of Bharata, there is decline of Dharma, and rise of Adharma, then I body Myself forth.', 'Bhagavad Gita 4.7', array['hope']::text[], array['low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('3f745431-2261-4597-a892-8b7bb7c876cc', (select id from public.guides where slug = 'bhagavad-gita'), 'Without hope, the body and mind controlled and all possessions relinquished, he does not suffer any evil consequences, by doing mere bodily action.', 'Bhagavad Gita 4.21', array['action', 'purpose', 'clarity', 'perspective', 'detachment', 'discipline', 'practice', 'hope']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'discontent', 'restless', 'low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('d00b8260-6faf-4794-ad33-5fa606357f19', (select id from public.guides where slug = 'bhagavad-gita'), 'With work renounced by Yoga and doubts rent asunder by knowledge, O Dhananjaya, actions do not bind him who is poised in the Self.', 'Bhagavad Gita 4.41', array['action', 'purpose', 'clarity', 'perspective', 'presence']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('d1675344-3641-45f0-a4de-3cec0e1ef8d0', (select id from public.guides where slug = 'bhagavad-gita'), 'Whose undertakings are all devoid of plan and desire for results, and whose actions are burnt by the fire of knowledge, him, the sages call wise.', 'Bhagavad Gita 4.19', array['action', 'purpose', 'clarity', 'perspective', 'presence', 'detachment']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e4fd292c-ed2e-44dc-8f2d-b4f1c3c0e6a1', (select id from public.guides where slug = 'bhagavad-gita'), 'Content with what comes to him without effort, unaffected by the pairs of opposites, free from envy, even-minded in success and failure, though acting, he is not bound.', 'Bhagavad Gita 4.22', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e763755b-ccff-4054-972c-dc1d8db01abb', (select id from public.guides where slug = 'bhagavad-gita'), 'Devoid of attachment, liberated, with mind centred in knowledge, performing work for Yajna alone, his whole Karma dissolves away.', 'Bhagavad Gita 4.23', array['action', 'purpose', 'clarity', 'perspective', 'presence', 'detachment', 'connection', 'support']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious', 'discontent', 'restless', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg09.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('77358cc6-997d-4999-8738-fc1795ec0632', (select id from public.guides where slug = 'bhagavad-gita'), 'He who does actions forsaking attachment, resigning them to Brahman, is not soiled by evil, like unto a lotus-leaf by water.', 'Bhagavad Gita 5.10', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('569f0128-77a0-42d7-9978-ed3e8160ed0e', (select id from public.guides where slug = 'bhagavad-gita'), 'The knowers of the Self look with an equal eye on a Brâhmana endowed with learning and humility, a cow, an elephant, a dog, and a pariah.', 'Bhagavad Gita 5.18', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('ee269b6d-e901-41ca-8415-f4642d8f93c9', (select id from public.guides where slug = 'bhagavad-gita'), 'Devotees in the path of work perform action, only with body, mind, senses, and intellect, forsaking attachment, for the purification of the heart.', 'Bhagavad Gita 5.11', array['action', 'purpose', 'clarity', 'perspective', 'love', 'support', 'detachment']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'guilty', 'tired', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('89c67ab2-7703-4972-b5c4-7091dda6698f', (select id from public.guides where slug = 'bhagavad-gita'), 'Released from lust and anger, the heart controlled, the Self realised, absolute freedom is for such Sannyâsis, both here and hereafter.', 'Bhagavad Gita 5.26', array['forgiveness', 'love', 'support', 'discipline', 'practice']::text[], array['angry', 'frustrated', 'guilty', 'tired', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('acf040a4-afbc-4f7c-9242-5e874e1b1151', (select id from public.guides where slug = 'bhagavad-gita'), 'The well-poised, forsaking the fruit of action, attains peace, born of steadfastness; the unbalanced one, led by desire, is bound by being attached to the fruit (of action).', 'Bhagavad Gita 5.12', array['peace', 'action', 'purpose', 'detachment']::text[], array['anxious', 'restless', 'stuck', 'unmotivated', 'discontent']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('df9f4274-4939-4dfe-8da3-c6801e34807f', (select id from public.guides where slug = 'bhagavad-gita'), 'With imperfections exhausted, doubts dispelled, senses controlled, engaged in the good of all beings, the Rishis obtain absolute freedom.', 'Bhagavad Gita 5.25', array['discipline', 'practice']::text[], array['unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('74db26a3-5284-4dc0-9059-055af189a2b1', (select id from public.guides where slug = 'bhagavad-gita'), 'With the mind purified by devotion to performance of action, and the body conquered, and senses subdued, one who realises one''s Self, as the Self in all beings, though acting, is not tainted.', 'Bhagavad Gita 5.7', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg10.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('6fc615d2-dd2f-4094-adf7-a49093d9cba3', (select id from public.guides where slug = 'bhagavad-gita'), 'Through whatever reason the restless, unsteady mind wanders away, let him curbing it from that, bring it under the subjugation of the Self alone.', 'Bhagavad Gita 6.26', array['clarity', 'perspective', 'connection', 'support']::text[], array['confused', 'overwhelmed', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('ac9988f5-e57f-44f2-9fdb-0b05bd96adbe', (select id from public.guides where slug = 'bhagavad-gita'), 'Without doubt, O mighty-armed, the mind is restless, and difficult to control; but through practice and renunciation, O son of Kunti, it may be governed.', 'Bhagavad Gita 6.35', array['action', 'purpose', 'clarity', 'perspective', 'discipline', 'practice']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('370fac7a-7ca7-4916-82a2-a5fd73eb6758', (select id from public.guides where slug = 'bhagavad-gita'), 'The self (the active part of our nature) is the friend of the self, for him who has conquered himself by this self. But to the unconquered self, this self is inimical, (and behaves) like (an external) foe.', 'Bhagavad Gita 6.6', array['action', 'purpose', 'love', 'support']::text[], array['stuck', 'unmotivated', 'guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('cac0669c-e679-4c6c-a83c-3b315b25e048', (select id from public.guides where slug = 'bhagavad-gita'), 'A man should uplift himself by his own self, so let him not weaken this self. For this self is the friend of oneself, and this self is the enemy of oneself.', 'Bhagavad Gita 6.5', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('3e53fb7d-6210-4a5f-aaca-b582331699d8', (select id from public.guides where slug = 'bhagavad-gita'), 'With the heart serene and fearless, firm in the vow of a Brahmachâri, with the mind controlled, and ever thinking of Me, let him sit (in Yoga) having Me as his supreme goal.', 'Bhagavad Gita 6.14', array['resilience', 'clarity', 'perspective', 'love', 'support', 'discipline', 'practice']::text[], array['fearful', 'insecure', 'confused', 'overwhelmed', 'guilty', 'tired', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('6ee0635e-2441-44e4-9215-2231e3a057f4', (select id from public.guides where slug = 'bhagavad-gita'), 'When the completely controlled mind rests serenely in the Self alone, free from longing after all desires, then is one called steadfast, (in the Self).', 'Bhagavad Gita 6.18', array['clarity', 'perspective', 'detachment', 'discipline', 'practice', 'connection', 'support']::text[], array['confused', 'overwhelmed', 'discontent', 'restless', 'unmotivated', 'stuck', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('fbe397e0-3a1e-4cd6-a51f-ea2d1ad4c422', (select id from public.guides where slug = 'bhagavad-gita'), 'With the intellect set in patience, with the mind fastened on the Self, let him attain quietude by degrees: let him not think of anything.', 'Bhagavad Gita 6.25', array['peace', 'clarity', 'perspective']::text[], array['anxious', 'restless', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e9d21abc-0137-4165-8ea6-26380074ea92', (select id from public.guides where slug = 'bhagavad-gita'), 'Whose heart is filled with satisfaction by wisdom and realisation, and is changeless, whose senses are conquered, and to whom a lump of earth, stone, and gold are the same: that Yogi is called steadfast.', 'Bhagavad Gita 6.8', array['action', 'purpose', 'clarity', 'perspective', 'love', 'support', 'impermanence', 'acceptance']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'guilty', 'tired', 'grieving', 'fearful']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('7910f9d1-b9dd-49b7-b4b3-f45f34677282', (select id from public.guides where slug = 'bhagavad-gita'), 'He who performs his bounden duty without leaning to the fruit of action —he is a renouncer of action as well as of steadfast mind: not he who is without fire, nor he who is without action.', 'Bhagavad Gita 6.1', array['action', 'purpose', 'clarity', 'perspective', 'detachment']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg11.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('a7222e77-be08-40b2-9950-e9cd6fa0684a', (select id from public.guides where slug = 'bhagavad-gita'), 'Of the strong, I am the strength devoid of desire and attachment. I am, O bull among the Bhâratas, desire in beings, unopposed to Dharma.', 'Bhagavad Gita 7.11', array['resilience', 'detachment']::text[], array['fearful', 'insecure', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg12.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('22757213-9cd5-4e01-a86c-5faeac6a569c', (select id from public.guides where slug = 'bhagavad-gita'), 'Four kinds of virtuous men worship Me, O Arjuna,—the distressed, the seeker of knowledge, the seeker of enjoyment, and the wise, O bull among the Bhâratas.', 'Bhagavad Gita 7.16', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg12.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('82e1010b-54d9-4ad1-9109-94c1bc040370', (select id from public.guides where slug = 'bhagavad-gita'), 'Noble indeed are they all, but the wise man I regard as My very Self; for with the mind steadfast, he is established in Me alone, as the supreme goal.', 'Bhagavad Gita 7.18', array['clarity', 'perspective', 'connection', 'support']::text[], array['confused', 'overwhelmed', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg12.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b2ba3fcb-a0bd-4635-b011-1f65c188631e', (select id from public.guides where slug = 'bhagavad-gita'), 'At the end of many births, the man of wisdom takes refuge in Me, realising that all this is Vâsudeva (the innermost Self). Very rare is that great soul.', 'Bhagavad Gita 7.19', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg12.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('6022812f-56f2-4ce6-a32b-1a67f826a28f', (select id from public.guides where slug = 'bhagavad-gita'), 'With the mind intent on Me, O son of Prithâ, taking refuge in Me, and practising Yoga, how thou shalt without doubt know Me fully, that do thou hear.', 'Bhagavad Gita 7.1', array['action', 'purpose', 'clarity', 'perspective', 'presence']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg12.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('fa006644-f1a2-465f-9c09-4db477f863a6', (select id from public.guides where slug = 'bhagavad-gita'), 'What the knowers of the Veda speak of as Imperishable, what the self-controlled (Sannyâsins), freed from attachment enter, and to gain which goal they live the life of a Brahmachârin, that I shall declare unto thee in brief.', 'Bhagavad Gita 8.11', array['clarity', 'perspective', 'presence', 'detachment', 'discipline', 'practice']::text[], array['confused', 'overwhelmed', 'anxious', 'discontent', 'restless', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg13.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('754226f4-813e-4fab-8ca7-7da1c9c900b5', (select id from public.guides where slug = 'bhagavad-gita'), 'Who, and in what way, is Adhiyajna here in this body, O destroyer of Madhu? And how art Thou known at the time of death, by the self-controlled?', 'Bhagavad Gita 8.2', array['clarity', 'perspective', 'presence', 'discipline', 'practice']::text[], array['confused', 'overwhelmed', 'anxious', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg13.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('efad9327-7fbe-4a5a-bd02-f2e38e40e203', (select id from public.guides where slug = 'bhagavad-gita'), 'I am easily attainable by that ever-steadfast Yogin who remembers Me constantly and daily, with a single mind, O son of Prithâ.', 'Bhagavad Gita 8.14', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg13.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b94b067a-206d-495e-8acb-2bc6d224a6cb', (select id from public.guides where slug = 'bhagavad-gita'), 'Therefore, at all times, constantly remember Me, and fight. With mind and intellect absorbed, in Me, thou shalt doubtless come to Me.', 'Bhagavad Gita 8.7', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg13.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('67987db5-dcb3-4149-8e70-85faf816fbd1', (select id from public.guides where slug = 'bhagavad-gita'), 'Persons who, meditating on Me as non-separate, worship Me in all beings, to them thus ever jealously engaged, I carry what they lack and preserve what they already have.', 'Bhagavad Gita 9.22', array['purpose']::text[], array['lost']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('31c717b0-f11d-4178-8cfe-48534bbcd06b', (select id from public.guides where slug = 'bhagavad-gita'), 'Of vain hopes, of vain works, of vain knowledge, and senseless, they verily are possessed of the delusive nature of Râkshasas and Asuras.', 'Bhagavad Gita 9.12', array['action', 'purpose', 'clarity', 'perspective', 'presence', 'detachment', 'hope']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious', 'discontent', 'restless', 'low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('afe4818b-5583-432a-a8ae-70d081161b43', (select id from public.guides where slug = 'bhagavad-gita'), 'Thus shalt thou be freed from the bondages of actions, bearing good and evil results: with the heart steadfast in the Yoga of renunciation, and liberated, thou shalt come unto Me.', 'Bhagavad Gita 9.28', array['action', 'purpose', 'love', 'support']::text[], array['stuck', 'unmotivated', 'guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('0aa9d45c-3031-41ce-bfc7-638b5d3ec3f9', (select id from public.guides where slug = 'bhagavad-gita'), 'Others, too, sacrificing by the Yajna of knowledge ( i.e., seeing the Self in all), worship Me the All-Formed, as one, as distinct, as manifold.', 'Bhagavad Gita 9.15', array['clarity', 'perspective', 'presence', 'connection', 'support']::text[], array['confused', 'overwhelmed', 'anxious', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('be2ebcd9-48f6-4be9-96c8-63ab7b9284a5', (select id from public.guides where slug = 'bhagavad-gita'), 'Whoever with devotion offers Me a leaf, a flower, a fruit, or water, that I accept—the devout gift of the pure-minded.', 'Bhagavad Gita 9.26', array['clarity', 'perspective', 'detachment']::text[], array['confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('d1645b41-833e-428e-a9cb-640bdbd50258', (select id from public.guides where slug = 'bhagavad-gita'), 'To thee, who dost not carp, verily shall I now declare this, the most profound knowledge, united with realisation, having known which, thou shalt be free from evil (Samsâra).', 'Bhagavad Gita 9.1', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('490b121c-7b8a-451b-855b-95fa368bac9a', (select id from public.guides where slug = 'bhagavad-gita'), 'By reason of My proximity, Prakriti produces all this, the moving and the unmoving; the world wheels round and round, O son of Kunti, because of this.', 'Bhagavad Gita 9.10', array['purpose']::text[], array['lost']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg14.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('1ad4de00-a8e5-44f6-8894-30acf37b2fca', (select id from public.guides where slug = 'bhagavad-gita'), 'Intellect, knowledge, non-delusion, forbearance, truth, restraint of the external senses, calmness of heart, happiness, misery, birth, death, fear, as well as fearlessness, non-injury, evenness, contentment, austerity, benevolence, good name, (as well as) ill-fame;—(these) different kinds of qualities of beings arise from Me alone.', 'Bhagavad Gita 10.4-5', array['peace', 'resilience', 'clarity', 'perspective', 'love', 'support', 'presence', 'discipline', 'practice', 'connection', 'hope']::text[], array['anxious', 'restless', 'fearful', 'insecure', 'confused', 'overwhelmed', 'guilty', 'tired', 'unmotivated', 'stuck', 'low']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg15.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('0c9aea72-293b-4d99-90b1-b5205443ad3e', (select id from public.guides where slug = 'bhagavad-gita'), 'Out of mere compassion for them, [paragraph continues] I, abiding in their hearts, destroy the darkness (in them) born of ignorance, by the luminous lamp of knowledge.', 'Bhagavad Gita 10.11', array['clarity', 'perspective', 'love', 'support', 'presence']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg15.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e3159933-14b9-4ecf-917b-9ff3f2324984', (select id from public.guides where slug = 'bhagavad-gita'), 'I am the Self, O Gudâkesha, existent in the heart of all beings; I am the beginning, the middle, and also the end of all beings.', 'Bhagavad Gita 10.20', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg15.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('825cb3cc-05dd-4a98-bdbd-b8f1eae271b8', (select id from public.guides where slug = 'bhagavad-gita'), 'Of manifestations I, am the beginning, the middle and also the end; of all knowledges I am the knowledge of the Self, and Vâda of disputants.', 'Bhagavad Gita 10.32', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg15.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('1814cef9-5f85-4213-afc9-a955b2f6d552', (select id from public.guides where slug = 'bhagavad-gita'), 'On seeing Thee touching the sky, shining in many a colour, with mouths wide open, with large fiery eyes, I am terrified at heart, and find no courage nor peace, O Vishnu.', 'Bhagavad Gita 11.24', array['peace', 'resilience', 'love', 'support']::text[], array['anxious', 'restless', 'fearful', 'insecure', 'guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg16.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('053e1321-e9f4-4ff9-aae5-bb6547709c2b', (select id from public.guides where slug = 'bhagavad-gita'), 'By the supremely profound words, on the discrimination of Self, that have been spoken by Thee out of compassion towards me, this my delusion is gone.', 'Bhagavad Gita 11.1', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg16.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('cbcfef93-1454-47e7-bf40-d119e25292c5', (select id from public.guides where slug = 'bhagavad-gita'), 'Having seen Thy mouths, fearful with tusks, (blazing) like Pralaya-fires, I know not the four quarters, nor do I find peace; have mercy, O Lord of the Devas, O Abode of the universe.', 'Bhagavad Gita 11.25', array['peace', 'resilience', 'clarity', 'perspective', 'presence']::text[], array['anxious', 'restless', 'fearful', 'insecure', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg16.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('9365a790-c066-4ad8-9a0d-bf152d558c1c', (select id from public.guides where slug = 'bhagavad-gita'), 'He by whom the world is not agitated and who cannot be agitated by the world, who is freed from joy, envy, fear and anxiety,—he is dear to Me.', 'Bhagavad Gita 12.15', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('ee19141e-30e4-49c4-921e-bee329cfb631', (select id from public.guides where slug = 'bhagavad-gita'), 'He who hates no creature, and is friendly and compassionate towards all, who is free from the feelings of ''I and mine,'' even-minded in pain and pleasure, forbearing, ever content, steady in meditation, self-controlled, and possessed of firm conviction, with mind and intellect fixed on Me,—he who is thus devoted to Me, is dear to Me.', 'Bhagavad Gita 12.13-14', array['healing', 'clarity', 'perspective', 'love', 'support', 'detachment', 'discipline', 'practice']::text[], array['grieving', 'low', 'confused', 'overwhelmed', 'guilty', 'tired', 'discontent', 'restless', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('5f8a41ca-b5a6-4205-9beb-49475f0a7473', (select id from public.guides where slug = 'bhagavad-gita'), 'If thou art unable to do even this, then taking refuge in Me, abandon the fruit of all action, self-controlled.', 'Bhagavad Gita 12.11', array['action', 'purpose', 'detachment', 'discipline', 'practice']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('95f83383-4dac-4fd3-adb0-51e625d29074', (select id from public.guides where slug = 'bhagavad-gita'), 'Better indeed is knowledge than (blind) Abhyâsa; meditation (with knowledge) is more esteemed than (mere) knowledge; than meditation the renunciation of the fruit of action; peace immediately follows renunciation.', 'Bhagavad Gita 12.12', array['peace', 'action', 'purpose', 'clarity', 'perspective', 'presence', 'detachment']::text[], array['anxious', 'restless', 'stuck', 'unmotivated', 'confused', 'overwhelmed', 'discontent']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('165d527d-e17a-4d4e-a654-84f13cf2dd57', (select id from public.guides where slug = 'bhagavad-gita'), 'He who neither rejoices, nor hates, nor grieves, nor desires, renouncing good and evil, full of devotion, he is dear to Me.', 'Bhagavad Gita 12.17', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('97ec207c-dd80-486d-b990-92f45204d3dd', (select id from public.guides where slug = 'bhagavad-gita'), 'But those who worship Me, resigning all actions in Me, regarding Me as the Supreme Goal, meditating on Me with single-minded Yoga,—to these whose mind is set on Me, verily, I become ere long, O son of Prithâ, the Saviour out of the ocean of the mortal Samsâra.', 'Bhagavad Gita 12.6-7', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('d31a5a82-c1e2-4c5b-b5b6-8e4065749aff', (select id from public.guides where slug = 'bhagavad-gita'), 'But those also, who worship the Imperishable, the Indefinable, the Unmanifested, the Omnipresent, the Unthinkable, the Unchangeable, the Immovable, the Eternal,—having subdued all the senses, even-minded everywhere, engaged in the welfare of all beings, verily, they reach only Myself.', 'Bhagavad Gita 12.3-4', array['forgiveness', 'clarity', 'perspective', 'presence', 'impermanence', 'acceptance']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'anxious', 'grieving', 'fearful']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('03b53566-8bbb-4599-9a04-4eaa9adc36bf', (select id from public.guides where slug = 'bhagavad-gita'), 'If also thou art unable to practise Abhyâsa, be thou intent on doing actions -for My sake. Even by doing actions for My sake, thou shalt attain perfection.', 'Bhagavad Gita 12.10', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg17.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('aa3ce8f9-9755-4f0d-8ec3-c295d7b4b314', (select id from public.guides where slug = 'bhagavad-gita'), 'Since seeing the Lord equally existent everywhere, he injures not Self by self, and so goes to the highest Goal.', 'Bhagavad Gita 13.28', array['purpose']::text[], array['lost']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg18.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('ad509d28-af2f-486f-9e09-5a22fc6cecc3', (select id from public.guides where slug = 'bhagavad-gita'), 'Some by meditation behold the Self in their own intelligence by the purified heart, others by the path of knowledge, others again by Karma Yoga.', 'Bhagavad Gita 13.24', array['clarity', 'perspective', 'love', 'support', 'presence', 'connection']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg18.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('8de4476a-ff0f-4a65-ab1a-dddb0444ea7e', (select id from public.guides where slug = 'bhagavad-gita'), 'The Light even of lights, It is said to be beyond darkness; Knowledge, and the One Thing to be known, the Goal of'' knowledge, dwelling in the hearts of all.', 'Bhagavad Gita 13.17', array['clarity', 'perspective', 'love', 'support', 'presence', 'hope']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious', 'low']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg18.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('41b803eb-eeb9-448f-8d2a-b69de0cbe272', (select id from public.guides where slug = 'bhagavad-gita'), 'Purusha seated in Prakriti, experiences the Gunas born of Prakriti; the reason of his birth in good and evil wombs is his attachment to the Gunas.', 'Bhagavad Gita 13.21', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg18.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('29d2d727-fb63-4af3-b473-4637d1b72409', (select id from public.guides where slug = 'bhagavad-gita'), 'He sees, who sees that all actions are done by Prakriti alone and that the Self is actionless.', 'Bhagavad Gita 13.29', array['action', 'purpose', 'connection', 'support']::text[], array['stuck', 'unmotivated', 'low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg18.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('e9a56e3b-f1fc-43ee-a884-3c8bddad5a01', (select id from public.guides where slug = 'bhagavad-gita'), 'He who hates not the appearance of light, (the effect of Sattva), activity (the effect of Rajas), and delusion (the effect of Tamas), (in his own mind), O Pândava, nor longs for them when absent;', 'Bhagavad Gita 14.22', array['action', 'purpose', 'clarity', 'perspective', 'hope']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg19.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('bcc73763-f068-47f0-a1b2-3d940d40ca72', (select id from public.guides where slug = 'bhagavad-gita'), 'Again shall I tell thee that supreme knowledge which is above all knowledge, having known which all the Munis have attained to high perfection after this life.', 'Bhagavad Gita 14.1', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg19.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('f86f6bd9-108e-4eda-bb76-a8bc3606997f', (select id from public.guides where slug = 'bhagavad-gita'), 'The fruit of good action, they say, is Sâttvika and pure; verily, the fruit of Rajas is pain, and ignorance is the fruit of Tamas.', 'Bhagavad Gita 14.16', array['action', 'purpose', 'healing', 'detachment']::text[], array['stuck', 'unmotivated', 'grieving', 'low', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg19.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('231e2a6f-bc9b-490a-8e37-4a640c6d2228', (select id from public.guides where slug = 'bhagavad-gita'), 'Greed, activity, the undertaking of actions, unrest, longing—these arise when Rajas is predominant, O bull of the: Bhâratas.', 'Bhagavad Gita 14.12', array['action', 'purpose', 'hope']::text[], array['stuck', 'unmotivated', 'low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg19.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('20c72121-2eb4-4a66-8566-725d4e0bb2ed', (select id from public.guides where slug = 'bhagavad-gita'), 'An eternal portion of Myself having become a living soul in the world of life, draws (to itself) the (five) senses with mind for the sixth, abiding in Prakriti.', 'Bhagavad Gita 15.7', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg20.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('1cc31ae8-a3d5-4f90-b1c1-cbd38f69d4d7', (select id from public.guides where slug = 'bhagavad-gita'), 'Free from pride and delusion, with the evil of attachment conquered, ever dwelling in the Self, with desires completely receded, liberated from the pairs of opposites known as pleasure and pain, the undeluded reach that Goal Eternal.', 'Bhagavad Gita 15.5', array['healing', 'clarity', 'perspective', 'presence', 'detachment']::text[], array['grieving', 'low', 'confused', 'overwhelmed', 'anxious', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg20.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('9c124b53-5afc-4e57-bdf5-e668b5e906ec', (select id from public.guides where slug = 'bhagavad-gita'), 'Him while transmigrating from one body to another, or residing (in the same) or experiencing, or when united with the Gunas,—the deluded do not see; but those who have the eye of wisdom behold Him.', 'Bhagavad Gita 15.10', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg20.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('720417b0-d1e4-47a9-a7e4-1d4a145fbcf1', (select id from public.guides where slug = 'bhagavad-gita'), 'I am centred in the hearts of all; memory and perception as well as their loss come from Me. I am verily that which has to be known by all the Vedas, I indeed am the Author of the Vedânta, and the Knower of the Veda am I.', 'Bhagavad Gita 15.15', array['healing', 'clarity', 'perspective', 'love', 'support', 'presence']::text[], array['grieving', 'low', 'confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg20.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('df5e5c4f-63bb-4867-8ec4-40e8af238900', (select id from public.guides where slug = 'bhagavad-gita'), 'Fearlessness, purity of heart, steadfastness in knowledge and Yoga; almsgiving, control of the senses, Yajna, reading of the Shâstras, austerity, uprightness;', 'Bhagavad Gita 16.1', array['resilience', 'clarity', 'perspective', 'love', 'support', 'presence', 'discipline', 'practice']::text[], array['fearful', 'insecure', 'confused', 'overwhelmed', 'guilty', 'tired', 'anxious', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg21.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('70da56b3-7b41-401e-9c48-118490be2a43', (select id from public.guides where slug = 'bhagavad-gita'), 'Filled with insatiable desires, full of hypocrisy, pride and arrogance, holding evil ideas through delusion, they work with impure resolve.', 'Bhagavad Gita 16.10', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg21.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('49fe3a8a-59b9-419f-b174-af213e3df619', (select id from public.guides where slug = 'bhagavad-gita'), 'Non-injury, truth, absence of anger, renunciation, tranquillity, absence of calumny, compassion to beings, un-covetousness, gentleness, modesty, absence of fickleness;', 'Bhagavad Gita 16.2', array['peace', 'forgiveness', 'clarity', 'perspective', 'love', 'support']::text[], array['anxious', 'restless', 'angry', 'frustrated', 'confused', 'overwhelmed', 'guilty', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg21.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('6a80b31e-07ed-4ac9-8d34-4eb326fb9284', (select id from public.guides where slug = 'bhagavad-gita'), 'The man who has got beyond these three gates of darkness, O son of Kunti, practises what is good for himself, and thus goes to the Goal Supreme.', 'Bhagavad Gita 16.22', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg21.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('ca57b051-ec60-47b4-a4c3-34b9aa521d58', (select id from public.guides where slug = 'bhagavad-gita'), 'The persons of Asurika nature know not what to do and what to refrain from; neither is purity found in them nor good conduct, nor truth.', 'Bhagavad Gita 16.7', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg21.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('c8e98044-3a43-486d-81c5-00d4a357cbcb', (select id from public.guides where slug = 'bhagavad-gita'), 'Bound by a hundred ties of hope, given over to lust and wrath, they strive to secure by unjust means hoards of wealth for sensual enjoyment.', 'Bhagavad Gita 16.12', array['forgiveness', 'hope']::text[], array['angry', 'frustrated', 'low', 'tired']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg21.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('bea6942f-1cc7-4d6d-be5d-29b841dc65b9', (select id from public.guides where slug = 'bhagavad-gita'), 'Speech which causes no vexation, and is true, as also agreeable and beneficial, and regular study of the Vedas,— these are said to form the austerity of speech.', 'Bhagavad Gita 17.15', array['purpose']::text[], array['lost']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg22.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('d4233353-74f1-4537-8cc4-3377cbc9feb5', (select id from public.guides where slug = 'bhagavad-gita'), 'Serenity of mind, kindliness, silence, self-control, honesty of motive,—this is called the mental austerity.', 'Bhagavad Gita 17.16', array['clarity', 'perspective', 'discipline', 'practice']::text[], array['confused', 'overwhelmed', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg22.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('f0e8356a-86bd-467b-ab8b-c58bf6992c9d', (select id from public.guides where slug = 'bhagavad-gita'), 'That Yajna is Sâttvika which is performed by men desiring no fruit, as enjoined by ordinance, with their mind fixed on the Yajna only, for its own sake.', 'Bhagavad Gita 17.11', array['clarity', 'perspective', 'detachment']::text[], array['confused', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg22.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('ce7cc036-f012-4c95-a5c3-68d4241764ac', (select id from public.guides where slug = 'bhagavad-gita'), 'The word Sat is used in the sense of reality and of goodness; and so also, Pârtha, the word Sat is used in the sense of an auspicious act.', 'Bhagavad Gita 17.26', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg22.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('844f3831-60b8-4e36-9f58-7a2d0e5a59eb', (select id from public.guides where slug = 'bhagavad-gita'), 'Better is one''s own Dharma, (though) imperfect, than the Dharma of another well-performed. He who does the duty ordained by his own nature incurs no evil.', 'Bhagavad Gita 18.47', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('616931de-135f-4f3b-a09f-caf895856c38', (select id from public.guides where slug = 'bhagavad-gita'), 'Relinquishing all Dharmas take refuge in Me alone; I will liberate thee from all sins; grieve not.', 'Bhagavad Gita 18.66', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('aa8d2926-5d32-492f-9f23-93ddd83cc232', (select id from public.guides where slug = 'bhagavad-gita'), 'But the action which is performed desiring desires, or with self-conceit and with much effort, is declared to be Râjasika.', 'Bhagavad Gita 18.24', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b4ae4ff0-64bf-4645-8492-472d3151dc1c', (select id from public.guides where slug = 'bhagavad-gita'), 'He whose intellect is unattached everywhere, who has subdued his heart, whose desires have fled, he attains by renunciation to the supreme perfection, consisting of freedom from action.', 'Bhagavad Gita 18.49', array['action', 'purpose', 'love', 'support', 'detachment']::text[], array['stuck', 'unmotivated', 'guilty', 'tired', 'discontent', 'restless']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('1d1631ac-dc8f-4e08-a445-8fdea4328e97', (select id from public.guides where slug = 'bhagavad-gita'), 'Learn from Me, O mighty-armed, these five causes for the accomplishment of all works as declared in the wisdom which is the end of all action:', 'Bhagavad Gita 18.13', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('b1eafb6c-3c87-450a-9d8f-1e007c064639', (select id from public.guides where slug = 'bhagavad-gita'), 'Knowledge, action and agent are declared in the Sânkhya philosophy to be of three kinds only, from the distinction of Gunas: hear them also duly.', 'Bhagavad Gita 18.19', array['action', 'purpose', 'clarity', 'perspective', 'presence']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('0bc9ef5b-bd7b-4458-8a0c-3adac721f07f', (select id from public.guides where slug = 'bhagavad-gita'), 'That which knows the paths of work and renunciation, right and wrong action, fear and fearlessness, bondage and liberation, that intellect, O Pârtha, is Sâttvika.', 'Bhagavad Gita 18.30', array['action', 'purpose', 'resilience', 'clarity', 'perspective', 'presence']::text[], array['stuck', 'unmotivated', 'fearful', 'insecure', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('99ee0ad3-130a-4c4b-9cc7-fb305d6883bc', (select id from public.guides where slug = 'bhagavad-gita'), 'The control of the mind and the senses, austerity, purity, forbearance, and also uprightness, knowledge, realisation, belief in a hereafter,—these are the duties of the Brâhmanas, born of (their own) nature.', 'Bhagavad Gita 18.42', array['clarity', 'perspective', 'presence', 'discipline', 'practice']::text[], array['confused', 'overwhelmed', 'anxious', 'unmotivated', 'stuck']::text[], 'direct_quote', 'Srimad Bhagavad Gita', 'https://archive.sacred-texts.com/hin/sbg/sbg23.htm', 'Swami Swarupananda', 'Public domain in the USA; Swami Swarupananda translation, 1909', null),
  ('defdc196-6922-4f8a-8018-59b2457fd27e', (select id from public.guides where slug = 'marcus-aurelius'), 'Of him also, to observe a constant tenor, (not interrupted, with any other cares and distractions,) in the study and esteem of philosophy: to be bountiful and liberal in the largest measure; always to hope the best; and to be confident that my friends love me.', 'Meditations 1.11', array['action', 'purpose', 'love', 'support', 'hope']::text[], array['stuck', 'unmotivated', 'guilty', 'tired', 'low']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('20bb3262-f518-44f1-a340-f6c16e9f4d22', (select id from public.guides where slug = 'marcus-aurelius'), 'Of my mother I have learned to be religious, and bountiful; and to forbear, not only to do, but to intend any evil; to content myself with a spare diet, and to fly all such excess as is incidental to great wealth.', 'Meditations 1.1', array['perspective']::text[], array['discontent']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('d0bb2389-cf6b-4df3-bb4e-9130e3a715ae', (select id from public.guides where slug = 'marcus-aurelius'), 'His care to preserve his friends; how neither at any time he would carry himself towards them with disdainful neglect, and grow weary of them; nor yet at any time be madly fond of them.', 'Meditations 1.13', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('e9c67693-1a4a-43d8-8281-4e5324011356', (select id from public.guides where slug = 'marcus-aurelius'), 'That I have had such a brother, who by his own example might stir me up to think of myself; and by his respect and love, delight and please me.', 'Meditations 1.14', array['love', 'support', 'hope']::text[], array['guilty', 'tired', 'low']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('668da49c-aca1-4468-908c-aed2ff8d5547', (select id from public.guides where slug = 'marcus-aurelius'), 'Thou must also take heed of another kind of wandering, for they are idle in their actions, who toil and labour in this life, and have no certain scope to which to direct all their motions, and desires.', 'Meditations 2.4', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('0d7cc22b-a21e-4b62-aa0d-6e842ddd1f6f', (select id from public.guides where slug = 'marcus-aurelius'), 'Remember how long thou hast already put off these things, and how often a certain day and hour as it were, having been set unto thee by the gods, thou hast neglected it.', 'Meditations 2.1', array['perspective']::text[], array['discontent']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('dbfb679c-b3e0-4cfc-ab3d-aaf6816a23e3', (select id from public.guides where slug = 'marcus-aurelius'), 'For he that is angry seems with a kind of grief and close contraction of himself, to turn away from reason; but he that sins through lust, being overcome by pleasure, doth in his very sin bewray a more impotent, and unmanlike disposition.', 'Meditations 2.7', array['action', 'purpose', 'healing']::text[], array['stuck', 'unmotivated', 'grieving', 'low']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('210c74a6-a14a-46ee-8fa2-b217b03cacf5', (select id from public.guides where slug = 'marcus-aurelius'), 'His service doth consist in this, that a man keep himself pure from all violent passion and evil affection, from all rashness and vanity, and from all manner of discontent, either in regard of the gods or men.', 'Meditations 2.11', array['perspective']::text[], array['discontent']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('fb960bed-bc25-4849-8152-0ca7355f4747', (select id from public.guides where slug = 'marcus-aurelius'), 'One who for his word or actions neither needs an oath, nor any man to be a witness.', 'Meditations 3.5', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('2ddc681a-795b-4076-82ba-837b8629eb6a', (select id from public.guides where slug = 'marcus-aurelius'), 'What is this, that now my fancy is set upon? of what things doth it consist? how long can it last? which of all the virtues is the proper virtue for this present use? as whether meekness, fortitude, truth, faith, sincerity, contentation, or any of the rest?', 'Meditations 3.12', array['forgiveness', 'clarity', 'perspective', 'presence']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('4d99fd48-3444-4fdd-bf66-0e28040580be', (select id from public.guides where slug = 'marcus-aurelius'), 'Casting therefore all other things aside, keep thyself to these few, and remember withal that no man properly can be said to live more than that which is now present, which is but a moment of time.', 'Meditations 3.10', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('52320f64-19a0-4d9c-8dc4-b85415f8088f', (select id from public.guides where slug = 'marcus-aurelius'), 'Hasten therefore to an end, and giving over all vain hopes, help thyself in time if thou carest for thyself, as thou oughtest to do.', 'Meditations 3.15', array['hope']::text[], array['low', 'tired']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('68c66aa1-5334-463f-9a80-ef98ac58f141', (select id from public.guides where slug = 'marcus-aurelius'), 'The next, that all these things, which now thou seest, shall within a very little while be changed, and be no more: and ever call to mind, how many changes and alterations in the world thou thyself hast already been an eyewitness of in thy time.', 'Meditations 4.3', array['clarity', 'perspective', 'presence', 'impermanence', 'acceptance']::text[], array['confused', 'overwhelmed', 'anxious', 'grieving', 'fearful']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('53002897-95b7-4a3b-8909-6081019702ab', (select id from public.guides where slug = 'marcus-aurelius'), 'For notwithstanding that such a multitude of them is daily consumed, and as it were buried in the bodies of the eaters, yet is the same place and body able to contain them, by reason of their conversion, partly into blood, partly into air and fire.', 'Meditations 4.17', array['perspective']::text[], array['discontent']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('cdb9da6d-ddf5-48cd-bc49-7d6e9ff28ec4', (select id from public.guides where slug = 'marcus-aurelius'), 'Try also how a good man''s life; (of one, who is well pleased with those things whatsoever, which among the common changes and chances of this world fall to his own lot and share; and can live well contented and fully satisfied in the justice of his own proper present action, and in the goodness of his disposition for the future:) will agree with thee.', 'Meditations 4.21', array['forgiveness', 'action', 'purpose', 'presence', 'impermanence', 'acceptance']::text[], array['angry', 'frustrated', 'stuck', 'unmotivated', 'anxious', 'overwhelmed', 'grieving', 'fearful']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('2631b938-40b0-4597-8fb0-db59a80a566f', (select id from public.guides where slug = 'marcus-aurelius'), 'This I understand even of those things, that are commonly called fair and good, as those which are commended either for the matter itself, or for curious workmanship.', 'Meditations 4.16', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('0e303a08-a796-44ec-baad-3c40ea54727a', (select id from public.guides where slug = 'marcus-aurelius'), 'Not to wander out of the way, but upon every motion and desire, to perform that which is just: and ever to be careful to attain to the true natural apprehension of every fancy, that presents itself.', 'Meditations 4.18', array['forgiveness', 'presence', 'detachment']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('1904a396-7540-4d8a-8e27-b5413875c294', (select id from public.guides where slug = 'marcus-aurelius'), 'In the morning when thou findest thyself unwilling to rise, consider with thyself presently, it is to go about a man''s work that I am stirred up.', 'Meditations 5.1', array['forgiveness', 'action', 'purpose', 'presence', 'hope']::text[], array['angry', 'frustrated', 'stuck', 'unmotivated', 'anxious', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('46fd7a78-8b92-45ab-96d7-291f859a2fdc', (select id from public.guides where slug = 'marcus-aurelius'), 'For she herself alone can affect and move herself, and according as the dogmata and opinions are, which she doth vouchsafe herself; so are those things which, as accessories, have any co-existence with her.', 'Meditations 5.16', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('772b2478-b4dc-4c14-b05b-bc971adcbfee', (select id from public.guides where slug = 'marcus-aurelius'), 'A happy lot and portion is, good inclinations of the soul, good desires, good actions.', 'Meditations 5.30', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('046b0be8-dd35-4e11-be74-2ff09f27b0de', (select id from public.guides where slug = 'marcus-aurelius'), 'But if thou dost desire to understand truly what it is that is said, fear not that thou shalt therefore give over any sociable action.', 'Meditations 5.6', array['action', 'purpose', 'resilience', 'detachment']::text[], array['stuck', 'unmotivated', 'fearful', 'insecure', 'discontent', 'restless']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('a5ee9bad-89ad-4d1d-9c52-cf7ab8702f74', (select id from public.guides where slug = 'marcus-aurelius'), 'Thou must comfort thyself in the expectation of thy natural dissolution, and in the meantime not grieve at the delay; but rest contented in those two things.', 'Meditations 5.10', array['perspective']::text[], array['discontent']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('cd1426ff-cc0d-4996-8552-b059c0002da9', (select id from public.guides where slug = 'marcus-aurelius'), 'Let this be thy only joy, and thy only comfort, from one sociable kind action without intermission to pass unto another, God being ever in thy mind.', 'Meditations 6.6', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('4f4d58cb-5bb6-4378-bcd0-a82bdc4da5b7', (select id from public.guides where slug = 'marcus-aurelius'), 'Unto my body all things are indifferent, for of itself it cannot affect one thing more than another with apprehension of any difference; as for my mind, all things which are not within the verge of her own operation, are indifferent unto her, and for her own operations, those altogether depend of her; neither does she busy herself about any, but those that are present; for as for future and past operations, those also are now at this present indifferent unto her.', 'Meditations 6.30', array['forgiveness', 'clarity', 'perspective', 'presence', 'connection', 'support']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'anxious', 'low', 'insecure']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('975e6ce4-027a-48ec-b86a-f51a9c4081f6', (select id from public.guides where slug = 'marcus-aurelius'), 'Keep thyself therefore, truly simple, good, sincere, grave, free from all ostentation, a lover of that which is just, religious, kind, tender-hearted, strong and vigorous to undergo anything that becomes thee.', 'Meditations 6.27', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('e306836b-70d1-4f6d-b53b-cd136db05abb', (select id from public.guides where slug = 'marcus-aurelius'), 'And my nature is, to be rational in all my actions and as a good, and natural member of a city and commonwealth, towards my fellow members ever to be sociably and kindly disposed and affected.', 'Meditations 6.39', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('2814308a-9be1-48d7-90a3-70858d310f42', (select id from public.guides where slug = 'marcus-aurelius'), 'But if thou shalt honour and respect thy mind only, that will make thee acceptable towards thyself, towards thy friends very tractable; and conformable and concordant with the Gods; that is, accepting with praises whatsoever they shall think good to appoint and allot unto thee.', 'Meditations 6.15', array['action', 'purpose', 'clarity', 'perspective', 'love', 'support']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'guilty', 'tired']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('18aa9791-314f-495a-8ec1-6577209ee15c', (select id from public.guides where slug = 'marcus-aurelius'), 'Thou must continually ponder and consider with thyself, what manner of men they be, and for their minds and understandings what is their present estate, whose good word and testimony thou dost desire.', 'Meditations 7.34', array['forgiveness', 'clarity', 'perspective', 'presence', 'detachment']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'anxious', 'discontent', 'restless']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('8b998f3e-5bba-4c51-a575-4ca0efe55b12', (select id from public.guides where slug = 'marcus-aurelius'), 'For there is good use to be made of them, and they will prove fit matter for thee to work upon, if it shall be both thy care and thy desire, that whatsoever thou doest, thou thyself mayst like and approve thyself for it.', 'Meditations 7.31', array['action', 'purpose', 'detachment']::text[], array['stuck', 'unmotivated', 'discontent', 'restless']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('87cf09ca-51fa-4bf7-9f7e-4519d08fc44b', (select id from public.guides where slug = 'marcus-aurelius'), 'Neither vexing himself to no purpose at the wickedness of others, nor yet ever condescending to any man''s evil fact, or evil intentions, through either fear, or engagement of friendship.', 'Meditations 7.37', array['action', 'purpose', 'resilience', 'love', 'support', 'connection']::text[], array['stuck', 'unmotivated', 'fearful', 'insecure', 'guilty', 'tired', 'low']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('d2c2b0ec-1a15-490c-b111-f37c01625e0e', (select id from public.guides where slug = 'marcus-aurelius'), 'Whensoever any man doth trespass against other, presently consider with thyself what it was that he did suppose to be good, what to be evil, when he did trespass.', 'Meditations 7.19', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('99fcf2fe-3616-42f7-92c5-5b493da48775', (select id from public.guides where slug = 'marcus-aurelius'), 'Where the matter may be effected agreeably to that reason, which both unto the Gods and men is common, there can be no just cause of grief or sorrow.', 'Meditations 7.29', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('bf430a7a-38e9-4ac8-a072-70763df48d79', (select id from public.guides where slug = 'marcus-aurelius'), 'If thou beest quick-sighted, be so in matter of judgment, and best discretion, saith he.', 'Meditations 8.36', array['perspective']::text[], array['discontent']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('b7140d27-e9eb-41d1-9b80-8eb147e5cf04', (select id from public.guides where slug = 'marcus-aurelius'), 'When thou art hard to be stirred up and awaked out of thy sleep, admonish thyself and call to mind, that, to perform actions tending to the common good is that which thine own proper constitution, and that which the nature of man do require.', 'Meditations 8.11', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('619e48a9-5c72-4af5-bc3a-33bde20aa728', (select id from public.guides where slug = 'marcus-aurelius'), 'As every fancy and imagination presents itself unto thee, consider (if it be possible) the true nature, and the proper qualities of it, and reason with thyself about it.', 'Meditations 8.12', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('23a90a92-35f1-4d73-9598-f9ee6fad76c5', (select id from public.guides where slug = 'marcus-aurelius'), 'But thou must not openly and vulgarly observe that sound and exact form of speaking, concerning that which is truly good and truly civil; the vanity of the world, and of worldly men: which otherwise truth and reason doth prescribe.', 'Meditations 8.28', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('c0ae396c-de6b-441e-ad91-ee5f61b018ef', (select id from public.guides where slug = 'marcus-aurelius'), 'Let not the general representation unto thyself of the wretchedness of this our mortal life, trouble thee.', 'Meditations 8.34', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('75e7ceb7-0067-47b7-b09a-7f86a1599d32', (select id from public.guides where slug = 'marcus-aurelius'), 'To wipe away fancy, to use deliberation, to quench concupiscence, to keep the mind free to herself.', 'Meditations 9.6', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('3ed2b36c-3443-4d76-8301-4724b7333d70', (select id from public.guides where slug = 'marcus-aurelius'), 'And thus when through the whole course of thy life hitherto thou hast found and observed many alterations, many changes, many kinds of endings and cessations, put this question to thyself What matter of grief or sorrow dost thou find in any of these?', 'Meditations 9.19', array['healing', 'impermanence', 'acceptance']::text[], array['grieving', 'low', 'fearful']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('df3e197d-6620-4c0b-9572-58c4080d38a4', (select id from public.guides where slug = 'marcus-aurelius'), 'To comprehend the whole world together in thy mind, and the whole course of this present age to represent it unto thyself, and to fix thy thoughts upon the sudden change of every particular object.', 'Meditations 9.31', array['forgiveness', 'clarity', 'perspective', 'presence', 'impermanence', 'acceptance', 'connection', 'support']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'anxious', 'grieving', 'fearful', 'low', 'insecure']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('d6817254-7622-4806-94c2-760854284c29', (select id from public.guides where slug = 'marcus-aurelius'), 'This also thou shalt find of very good use, upon every such occasion, presently to consider with thyself, what proper virtue nature hath furnished man with, against such a vice, or to encounter with a disposition vicious in this kind.', 'Meditations 9.43', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('0c0b5458-8d20-443f-b9a3-b06fb44214da', (select id from public.guides where slug = 'marcus-aurelius'), 'As for unreasonable creatures then, they had not long been, but presently begun among them swarms, and flocks, and broods of young ones, and a kind of mutual love and affection.', 'Meditations 9.7', array['forgiveness', 'love', 'support', 'presence']::text[], array['angry', 'frustrated', 'guilty', 'tired', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('e7151114-c03d-4623-adeb-7a007ab53d08', (select id from public.guides where slug = 'marcus-aurelius'), 'And it is not out of a stout and peremptory resolution, that he saith it, but in mere love, and humble submission.', 'Meditations 10.16', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('66007b2c-9b5d-47d0-a0c6-ce37b9929cb7', (select id from public.guides where slug = 'marcus-aurelius'), 'When thou art offended with any man''s transgression, presently reflect upon thyself; and consider what thou thyself art guilty of in the same kind.', 'Meditations 10.30', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('35ae44ae-7d6f-48e6-a71f-c2be1100f046', (select id from public.guides where slug = 'marcus-aurelius'), 'To find out, and set to thyself some certain way and method of contemplation, whereby thou mayest clearly discern and represent unto thyself, the mutual change of all things, the one into the other.', 'Meditations 10.11', array['forgiveness', 'presence', 'impermanence', 'acceptance']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed', 'grieving', 'fearful']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('564c419c-0736-4a55-8417-d72430f60b0e', (select id from public.guides where slug = 'marcus-aurelius'), 'Especially when thou shalt call to mind this also, that whatsoever is once changed, shall never be again as long as the world endureth.', 'Meditations 10.31', array['resilience', 'clarity', 'perspective', 'impermanence', 'acceptance']::text[], array['fearful', 'insecure', 'confused', 'overwhelmed', 'grieving']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('537b7671-e58c-40ed-aa49-50a7311e40a1', (select id from public.guides where slug = 'marcus-aurelius'), 'For the motion of the mind to any injustice, or incontinency, or to sorrow, or to fear, is nothing else but a separation from nature.', 'Meditations 11.18', array['resilience', 'healing', 'clarity', 'perspective']::text[], array['fearful', 'insecure', 'grieving', 'low', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('59b73bac-d413-4d73-a50e-5275ca7639c8', (select id from public.guides where slug = 'marcus-aurelius'), 'No sooner thy voice is heard, than thy countenance must be able to show what is in thy mind: even as he that is loved knows presently by the looks of his sweetheart what is in her mind.', 'Meditations 11.14', array['forgiveness', 'clarity', 'perspective', 'love', 'support', 'presence']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('4e837e85-4763-4cd8-84c3-b71b45c52a29', (select id from public.guides where slug = 'marcus-aurelius'), 'In matter of writing or reading thou must needs be taught before thou can do either: much more in matter of life. ''For thou art born a mere slave, to thy senses and brutish affections;'' destitute without teaching of all true knowledge and sound reason.', 'Meditations 11.27', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('cfcc99d0-3230-419c-a903-8cea01a108d7', (select id from public.guides where slug = 'marcus-aurelius'), 'And that will be, if thou shalt forget all that is past, and for the future, refer thyself wholly to the Divine Providence, and shalt bend and apply all thy present thoughts and intentions to holiness and righteousness.', 'Meditations 12.1', array['forgiveness', 'clarity', 'perspective', 'presence']::text[], array['angry', 'frustrated', 'confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('b10d15fc-32a6-44dd-ad62-1db8215b03a3', (select id from public.guides where slug = 'marcus-aurelius'), 'If all be a mere confusion without any moderator, or governor, then hast thou reason to congratulate thyself; that in such a general flood of confusion thou thyself hast obtained a reasonable faculty, whereby thou mayest govern thine own life and actions.', 'Meditations 12.11', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('1729cfcb-5954-4fe7-8d02-0e47bcd019ab', (select id from public.guides where slug = 'marcus-aurelius'), 'Herein doth consist happiness of life, for a man to know thoroughly the true nature of everything; what is the matter, and what is the form of it: with all his heart and soul, ever to do that which is just, and to speak the truth.', 'Meditations 12.22', array['clarity', 'perspective', 'love', 'support', 'presence']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Meditations', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', 'Meric Casaubon', 'Public domain in the USA; Meric Casaubon translation', null),
  ('1acdc46b-4e50-4dff-8ffd-2a85dc528584', (select id from public.guides where slug = 'marcus-aurelius'), 'I learn from you to speak the truth, and to hear the truth without disguise.', 'Correspondence with Fronto, Ad M. Caes. 3.12', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('105a7417-1e39-4990-925a-9a3c83b61137', (select id from public.guides where slug = 'marcus-aurelius'), 'I prefer to write unwisely rather than to be silent unkindly.', 'Correspondence with Fronto, Ad M. Caes. 2.2', array['perspective']::text[], array['discontent']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('04853c86-5131-4f35-88c1-1f85d05bbf38', (select id from public.guides where slug = 'marcus-aurelius'), 'What concerns the case must be clearly brought forward; what concerns personal feeling should be left unsaid.', 'Correspondence with Fronto, Ad M. Caes. 3.5 (paraphrase)', array['perspective']::text[], array['discontent']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('55ac0d6a-972d-4b2f-a5cb-d56caca4c725', (select id from public.guides where slug = 'marcus-aurelius'), 'I cannot endure to write to you unless my mind is at ease, untroubled, and free.', 'Correspondence with Fronto, Ad M. Caes. 3.21', array['resilience', 'clarity', 'perspective']::text[], array['fearful', 'insecure', 'confused', 'overwhelmed']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('dbd84c32-a74b-4cc9-b599-b3dc7ec5ad32', (select id from public.guides where slug = 'marcus-aurelius'), 'Farewell, my master, always in every chance first in my mind, as you deserve to be.', 'Correspondence with Fronto, Ad M. Caes. 3.21', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('1a5d2e32-4d76-43c3-8a18-b067d31c7183', (select id from public.guides where slug = 'marcus-aurelius'), 'When you rest and do what is good for your health, I too am the better for it.', 'Correspondence with Fronto, letter of 139 CE', array['perspective']::text[], array['discontent']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('5ca59e05-8156-4335-80cb-b0ae0763e32d', (select id from public.guides where slug = 'marcus-aurelius'), 'When you lie ill, my spirit also lies low; when you stand upright, my spirit stands firm.', 'Correspondence with Fronto, Ad M. Caes. 3.19 (paraphrase)', array['perspective']::text[], array['discontent']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('73e2c150-ad5a-4e66-aeca-dfc4405ce68c', (select id from public.guides where slug = 'marcus-aurelius'), 'After returning home, I went straight to my books.', 'Correspondence with Fronto, Ad M. Caes. 4.5', array['perspective']::text[], array['discontent']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('08a668d6-ca9f-4e7a-8a3f-3abfa22ee1ec', (select id from public.guides where slug = 'marcus-aurelius'), 'I did my task and gave an account of the day to my delightful master.', 'Correspondence with Fronto, Ad M. Caes. 4.6', array['hope']::text[], array['low', 'tired']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('39d6b135-637d-48d3-bc6a-b8ce502e8398', (select id from public.guides where slug = 'marcus-aurelius'), 'I can love you while far away.', 'Correspondence with Fronto, Ad M. Caes. 4.6', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('e2932484-371b-4dff-941a-33fdd9365f28', (select id from public.guides where slug = 'marcus-aurelius'), 'If you miss me and love me, send your letters often; they are a comfort and consolation to me.', 'Correspondence with Fronto, Ad Verum Imp. 2.1', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('cecb6b39-bc38-4770-b7c3-477bcd992190', (select id from public.guides where slug = 'marcus-aurelius'), 'I would rather hear honest correction than praise that leaves me unchanged.', 'Correspondence with Fronto, Ad M. Caes. 3.12 (paraphrase)', array['impermanence', 'acceptance']::text[], array['grieving', 'fearful']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('5d35b9f0-435e-4a2f-9b29-7e5bfaef2153', (select id from public.guides where slug = 'marcus-aurelius'), 'The intention of friendship is shown by speaking before silence becomes unkind.', 'Correspondence with Fronto, Ad M. Caes. 2.2 (paraphrase)', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'paraphrase', 'Correspondence with Fronto', 'https://www.gutenberg.org/cache/epub/2680/pg2680.txt', null, 'Public-domain correspondence reproduced in the Project Gutenberg edition of Meditations', null),
  ('a137ba6c-e0ce-4a23-843e-062624319e35', (select id from public.guides where slug = 'rumi'), 'When ''tis knowledge of the heart, it is a friend; When knowledge of the body, it is a burden.', 'Masnavi, Book 1, STORY XIV. The Chinese and the Greek Artists.', array['clarity', 'perspective', 'love', 'support', 'presence']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_I', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('ca10cfb2-bbcf-47c0-bc17-e55efb99adaf', (select id from public.guides where slug = 'rumi'), 'LOVE desires that this secret should be revealed, For if a mirror reflects not, of what use is it?', 'Masnavi, Book 1, PROLOGUE.', array['love', 'support', 'detachment']::text[], array['guilty', 'tired', 'discontent', 'restless']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_I', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('7e901484-2eaf-48bd-b20e-05e6572def87', (select id from public.guides where slug = 'rumi'), 'Men''s minds recognize these second causes, But only prophets perceive the action of the First Cause.', 'Masnavi, Book 1, STORY IV. Another Tyrannical Jewish King.', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_I', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('6f5e709e-03ae-4a76-a8ec-d49660cb9b62', (select id from public.guides where slug = 'rumi'), 'This husband and wife are the reason and the flesh, A couple joined together for good and for evil.', 'Masnavi, Book 1, STORY IX. The Arab and his Wife.', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_I', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('8c8e45c3-5ee9-4d95-a160-7b43d75af9fb', (select id from public.guides where slug = 'rumi'), 'Till man destroys "self" he is no true friend of God. Once a man came and knocked at the door of his friend.', 'Masnavi, Book 1, STORY XI. The Lion who Hunted with the Wolf and the Fox.', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_I', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('6dcd7514-1560-4dce-8eef-9b91c111144a', (select id from public.guides where slug = 'rumi'), 'Their real aim and purpose being quite otherwise. Evil itself is turned into good for the good.', 'Masnavi, Book 2, STORY X. Bayazid and the Saint.', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_II', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('ee2541c4-c6b2-4705-9275-f9ad8da31d9e', (select id from public.guides where slug = 'rumi'), 'In the hearts of every sect that has a taste of the truth The sight and the voice of prophets work miracles.', 'Masnavi, Book 2, STORY XVI. The Gluttonous Sufi.', array['action', 'purpose', 'clarity', 'perspective', 'love', 'support']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_II', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('e5c4370c-b7ff-4404-b009-08b80ec81168', (select id from public.guides where slug = 'rumi'), 'You have seen many more wondrous works done by me, But where is the base man who accepts the truth?', 'Masnavi, Book 2, STORY VIII. The Man who made a Pet of a Bear.', array['action', 'purpose', 'clarity', 'perspective']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_II', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('76179ee3-85dd-4534-a318-a9a470e01713', (select id from public.guides where slug = 'rumi'), 'How can we suppose a transitory being spoken of by God? The Friend of God said, "I love not them that set?"', 'Masnavi, Book 2, STORY I. The Sufi''s Beast', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_II', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('cb2a1fa4-e1a6-4be9-92e0-0f3755719bc5', (select id from public.guides where slug = 'rumi'), 'Ah! sweep out of your heart these evil suggestions. Cry, "There is no power nor strength but in God!"', 'Masnavi, Book 2, STORY II. The Pauper and the Prisoners.', array['resilience', 'love', 'support']::text[], array['fearful', 'insecure', 'guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_II', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('fc61189f-c8cf-4861-9ad7-9cd89c2c6285', (select id from public.guides where slug = 'rumi'), 'O lover, cold-hearted and void of loyalty, Who from fear for your life shun the beloved!', 'Masnavi, Book 3, STORY XVII. The Vakil of the Prince of Bokhara.', array['resilience', 'love', 'support']::text[], array['fearful', 'insecure', 'guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_III', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('1ae8a657-3d2c-463f-af85-eb1643009c3c', (select id from public.guides where slug = 'rumi'), 'Because pain and sorrow and loads of cares Are the lot of God''s friends in the world.', 'Masnavi, Book 3, STORY I. The Travelers who ate the Young Elephant.', array['healing', 'love', 'support']::text[], array['grieving', 'low', 'guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_III', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('b0ca62ca-9f00-4c18-8af3-9852df2b5568', (select id from public.guides where slug = 'rumi'), 'Thou holdest thyself out as a lover of God, But thou hast coquetted with the evil demon.', 'Masnavi, Book 3, STORY II. The Villager who invited the Townsman to visit him.', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_III', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('c18dca15-49ee-4086-acb3-85a6e83f56e2', (select id from public.guides where slug = 'rumi'), 'Eat the words of wisdom, for veiled light Is not accepted in preference to unveiled light.', 'Masnavi, Book 3, STORY V. The Elephant in a Dark Room.', array['clarity', 'perspective', 'hope']::text[], array['confused', 'overwhelmed', 'low', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_III', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('c8dc82f5-e9c3-4829-a826-0eb38745e537', (select id from public.guides where slug = 'rumi'), 'Desire and appetite, which are the reins of mankind, Are themselves subservient to the rule of God.', 'Masnavi, Book 3, STORY XI. Bahlol and the Darvesh.', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_III', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('90b057fa-0b17-4237-9304-c4236420e8f9', (select id from public.guides where slug = 'rumi'), 'Arise, O lovers; this sweet draught is yours; Ye are they that endure; eternal life is yours.', 'Masnavi, Book 4, STORY II. The Building of the "Most Remote Temple" at Jerusalem.', array['resilience', 'love', 'support', 'hope']::text[], array['fearful', 'insecure', 'guilty', 'tired', 'low']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_IV', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('06f0a49a-79f0-4313-9f5b-385a8ced684d', (select id from public.guides where slug = 'rumi'), 'In the judgment of reason this gold is foul dung, Although, like dung, it serves to kindle the fire.', 'Masnavi, Book 4, STORY I. The Lover and his Mistress.', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_IV', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('c1bd981c-b808-4397-8f3a-21b08c35f2fe', (select id from public.guides where slug = 'rumi'), 'The officer then loses his power and hides himself. Reason is God''s shadow; God is the sun.', 'Masnavi, Book 4, STORY IV. Bayazid and his impious sayings when beside himself.', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_IV', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('d120cfe3-de64-4814-add1-fd42d202c790', (select id from public.guides where slug = 'rumi'), 'The man recovered himself and said, "Well then, Tell me now your third good counsel!"', 'Masnavi, Book 4, STORY V. The Three Fishes.', array['presence']::text[], array['anxious', 'overwhelmed']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_IV', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('cf98df0c-e434-4672-abfa-ad13362962d3', (select id from public.guides where slug = 'rumi'), 'When one has not done the work he gets no wages; "Man gets nothing he has not worked for."', 'Masnavi, Book 4, STORY VI. Moses and Pharaoh 1.', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_IV', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('c6346607-ca8b-4829-b19f-7fa448aef4ed', (select id from public.guides where slug = 'rumi'), 'God made reason a reader of all these letters, To suggest to it reflections on that outpouring of grace.', 'Masnavi, Book 5, STORY I. The Prophet and his Infidel Guest.', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_V', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('218fd41f-de98-4911-9b98-16e506f3e93c', (select id from public.guides where slug = 'rumi'), 'A reward that enchants the heart and charms the soul! Prayers to God to change our base inclinations and give us higher aspirations.', 'Masnavi, Book 5, STORY III. The Sage and the Peacock.', array['love', 'support', 'impermanence', 'acceptance']::text[], array['guilty', 'tired', 'grieving', 'fearful']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_V', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('bbabfd47-c063-4ba6-b0ef-a9e5cf0ec6d6', (select id from public.guides where slug = 'rumi'), 'I am not in a position to obey or not at will. Death is gain, for "God will change their evil things into good things."', 'Masnavi, Book 5, STORY VII. How Adam was created out of a handful of earth brought by an Angel.', array['impermanence', 'acceptance']::text[], array['grieving', 'fearful']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_V', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('824b0ee2-7b2c-4df1-ade3-31835c5eb2b7', (select id from public.guides where slug = 'rumi'), 'If a tender friend treats you roughly to try you, ''Tis contrary to reason to distrust him.', 'Masnavi, Book 5, STORY X. The Lion, the Fox, and the Ass.', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_V', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('f642284d-c13b-4786-8884-064b0e982614', (select id from public.guides where slug = 'rumi'), 'His love pitched its tent on the heavens, He himself was as the dog at the tent-door.', 'Masnavi, Book 5, STORY VIII. (continued). Mahmud and Ayaz.', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_V', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('27933e17-c86f-4ee3-ba84-75c2b6e8be43', (select id from public.guides where slug = 'rumi'), 'They bowed before it as body does before soul. Fear of men''s censure the greatest obstacle to acceptance of the true faith.', 'Masnavi, Book 6, PROLOGUE.', array['resilience']::text[], array['fearful', 'insecure']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_VI', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('5996125a-35b2-4efa-b550-8cb043840671', (select id from public.guides where slug = 'rumi'), 'One plunged in calamities like Job himself, Another exhibiting patience like Jacob.', 'Masnavi, Book 6, STORY III. The Drunken Turkish Amir and the Minstrel.', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_VI', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('fe3f759d-1133-4fcd-9b3b-c51137a48295', (select id from public.guides where slug = 'rumi'), 'Rustam and Hamza would be all the same as cowards; Wisdom and knowledge would be useless and vain.', 'Masnavi, Book 6, STORY V. The Sufi and the Qazi.', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_VI', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('9ca5cf12-1b86-4e27-9129-389d3a7bbbd2', (select id from public.guides where slug = 'rumi'), 'Therefore that Lord of the heart set up a Khalifa, To serve as a mirror to reflect His own sovereignty.', 'Masnavi, Book 6, STORY VI. The Faqir and the Hidden Treasure.', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_VI', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('a96b9619-d483-412b-a766-88b0be6c0d62', (select id from public.guides where slug = 'rumi'), 'The Truth is yourself, but not your mere bodily self, Your real self is higher than ''you'' and ''me.''', 'Masnavi, Book 6, STORY IX. The King and his Three Sons.', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Masnavi', 'https://en.wikisource.org/wiki/Masnavi_I_Ma%27navi/Book_VI', 'E. H. Whinfield', 'Public domain; E. H. Whinfield translation, 1898', null),
  ('e16fbce6-907d-47ab-bd0a-9d0f56c60399', (select id from public.guides where slug = 'rumi'), '‘ God is most great ’ is on my heart’s lips every moment. The heart hath gotten an eye constant in desire of thee.', 'Divan-e Shams, Nicholson selection, p. 43', array['love', 'support', 'presence', 'detachment']::text[], array['guilty', 'tired', 'anxious', 'overwhelmed', 'discontent', 'restless']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('0445443a-3696-41c1-82e0-3d4d1e5efa42', (select id from public.guides where slug = 'rumi'), 'Bankrupt tho’ I be, I will not accept a small carnelian; The mine of rare tremulous carnelian is my desire.', 'Divan-e Shams, Nicholson selection, p. 9', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('3d352b02-9205-4e21-8bdb-3d18a6979e85', (select id from public.guides where slug = 'rumi'), 'The face of Shamsi Din, Tabriz’s glory, is the sun In whose track the cloud-like hearts are moving.', 'Divan-e Shams, Nicholson selection, p. 27', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('a32e9152-a541-4af9-a329-00422ff9e6de', (select id from public.guides where slug = 'rumi'), 'Show thy face, for I desire the orchard and the rose-garden; Ope thy lips, for I desire sugar in plenty.', 'Divan-e Shams, Nicholson selection, p. 65', array['detachment']::text[], array['discontent', 'restless']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('b5f0ff4a-22ea-4fef-a281-ccf86ed146cd', (select id from public.guides where slug = 'rumi'), 'With set purpose I fared to the summit of Mount Qaf; In that place was only the ‘Anqa’s habitation.', 'Divan-e Shams, Nicholson selection, p. 73', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('d212fa37-e73c-402d-86b5-3fb548593fdc', (select id from public.guides where slug = 'rumi'), 'The sea broke into waves, and again Wisdom rose And cast abroad ^ voice; so it happened and thus it befell.', 'Divan-e Shams, Nicholson selection, p. 77', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('7f56a97f-532c-457f-8c4d-4b2923b70244', (select id from public.guides where slug = 'rumi'), 'The second soul which the vulgar know not I protest by God that he surrendered to the Beloved.', 'Divan-e Shams, Nicholson selection, p. 87', array['clarity', 'perspective', 'love', 'support', 'presence']::text[], array['confused', 'overwhelmed', 'guilty', 'tired', 'anxious']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('e33190dc-2b11-429e-b00b-0dcd2735a6aa', (select id from public.guides where slug = 'rumi'), 'Show a house that is not filled by him with lamps, Show a portico that his face filled not with loveliness.', 'Divan-e Shams, Nicholson selection, p. 91', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('6bb8a377-c495-447e-b8d9-67bfcbe33ea6', (select id from public.guides where slug = 'rumi'), 'I hold ray peace and keep the unworthy in the dark; Thou art all that is worthy : the mystery is veiled from me.', 'Divan-e Shams, Nicholson selection, p. 103', array['peace']::text[], array['anxious', 'restless']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('098ba806-db3b-42ad-9f6b-ae52b0a87c43', (select id from public.guides where slug = 'rumi'), 'Tho* you have no feet choose to joymey in yourself, Like the ruby-mine receive a print from the sunbeams.', 'Divan-e Shams, Nicholson selection, p. 110', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('b869ae0d-ad95-46a2-97b4-ccfa5f8319b6', (select id from public.guides where slug = 'rumi'), 'The heart’s home, first to last, is thy city of union : How long wilt thou keep in exile this heart forlorn?', 'Divan-e Shams, Nicholson selection, p. 13', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('5392e001-9d2e-4620-8a08-140e7ec7f0dd', (select id from public.guides where slug = 'rumi'), 'Life is the vessels, union the clear draught in them; Without thee what does the pain of the vessels avail me?', 'Divan-e Shams, Nicholson selection, p. 25', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('8dbd8dc9-6a7c-4581-a782-750ca981099d', (select id from public.guides where slug = 'rumi'), 'In the vessel where thou givest colour to the soul Who am I, what is my love and hate?', 'Divan-e Shams, Nicholson selection, p. 121', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('e11a0537-8fec-4556-a3b5-8d4b510d8be9', (select id from public.guides where slug = 'rumi'), 'How pleasant are the pains he makes thee suffer while he gently draws thee to himself!', 'Divan-e Shams, Nicholson selection, p. 143', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('5f729a21-af3a-4ba3-92f2-f43245daf7d9', (select id from public.guides where slug = 'rumi'), 'Thou gatherest up thy garment lest the water should wet it : Needs must thou plunge a thousand times in the sea.', 'Divan-e Shams, Nicholson selection, p. 5', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('a0149abd-d9ec-4319-9dc3-99e264a6652e', (select id from public.guides where slug = 'rumi'), 'Salahu ’lhaq ii din will declare to thee The beauty of our Sultan, the King of kings.', 'Divan-e Shams, Nicholson selection, p. 11', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('cbeff7e0-698c-43d2-ad5d-9f4fc616715e', (select id from public.guides where slug = 'rumi'), 'The man of God is distraught and bewildered. The man of God has no food or sleep.', 'Divan-e Shams, Nicholson selection, p. 1', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('60739a0b-8c71-4eb3-8eb5-cf9cb15822c3', (select id from public.guides where slug = 'rumi'), 'The man of God is beyond infidelity and religion, To the man of God right and wrong are alike.', 'Divan-e Shams, Nicholson selection, p. 31', array['healing']::text[], array['grieving']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('b434b603-dd65-44da-9841-c690c25657a4', (select id from public.guides where slug = 'rumi'), 'Yea, for it is a rule as regards the poor sick wretch. That while his pain is more his plaint is less.', 'Divan-e Shams, Nicholson selection, p. 44', array['healing']::text[], array['grieving', 'low']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('4e57cb86-b9b4-4cfc-89ee-f6ed95447622', (select id from public.guides where slug = 'rumi'), 'God revealed By the mo^''ning splendour” in envy of the light of his countenance.', 'Divan-e Shams, Nicholson selection, p. 93', array['hope']::text[], array['low', 'tired']::text[], 'direct_quote', 'Selected Poems from the Divan-e Shams', 'https://dn790000.ca.archive.org/0/items/in.ernet.dli.2015.52959/2015.52959.Selected-Poems-From-The-Divani-Shamsi-Tabriz_djvu.txt', 'R. A. Nicholson', 'Public domain; R. A. Nicholson translation, 1898', null),
  ('67cd2d95-2a87-46fe-8fbd-6945d9469414', (select id from public.guides where slug = 'camus'), 'Absurd awareness begins when familiar routines stop feeling self-evident.', 'The Myth of Sisyphus — An Absurd Reasoning', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('eaae758d-c80d-4f4e-834a-5158e78854a1', (select id from public.guides where slug = 'camus'), 'The question of whether life is worth living comes before abstract systems about it.', 'The Myth of Sisyphus — An Absurd Reasoning', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('01ccdcb5-c9f0-4ff9-8d53-38ad3a691662', (select id from public.guides where slug = 'camus'), 'The absurd arises where the human demand for clarity meets a world that gives no final answer.', 'The Myth of Sisyphus — Absurd Walls', array['hope']::text[], array['low', 'tired']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('93720575-090a-47da-9e22-7245712e61d7', (select id from public.guides where slug = 'camus'), 'Acknowledging the limits of reason does not require abandoning reason.', 'The Myth of Sisyphus — Philosophical Suicide', array['clarity', 'perspective', 'presence']::text[], array['confused', 'overwhelmed', 'anxious']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('6b9e40a3-a908-4f38-9cfb-f4151b942c95', (select id from public.guides where slug = 'camus'), 'Lucidity refuses both false consolation and passive despair.', 'The Myth of Sisyphus — Absurd Freedom', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('d0565218-b530-4fa3-82f9-f7120048363a', (select id from public.guides where slug = 'camus'), 'What matters is staying with the question instead of escaping through invented certainty.', 'The Myth of Sisyphus — Absurd Freedom', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('213cd40c-bfd0-4f1e-a78c-d8b3b2934710', (select id from public.guides where slug = 'camus'), 'Freedom grows when inherited guarantees no longer dictate how life must be lived.', 'The Myth of Sisyphus — Absurd Freedom', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('553ad536-120f-4257-8608-0a6f2a08daa6', (select id from public.guides where slug = 'camus'), 'The absence of a final explanation still leaves room for conscious choice.', 'The Myth of Sisyphus — Absurd Freedom', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('cee8783c-a243-4bf2-839d-5b97eace43a5', (select id from public.guides where slug = 'camus'), 'Revolt is the repeated decision to live without denying contradiction.', 'The Myth of Sisyphus — Absurd Freedom', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('a0a8e602-577d-4aa3-bb76-a6b53bac34a0', (select id from public.guides where slug = 'camus'), 'Intensity depends on attention to experience rather than promises about another life.', 'The Myth of Sisyphus — Absurd Freedom', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('cdb0b277-cbc1-4d98-899d-fa4409f39353', (select id from public.guides where slug = 'camus'), 'Don Juan represents a multiplicity of experience, not the discovery of one final possession.', 'The Myth of Sisyphus — Don Juanism', array['forgiveness', 'presence', 'detachment']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed', 'discontent', 'restless']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('934be57f-dc7b-4ba9-99d9-f2532a47112a', (select id from public.guides where slug = 'camus'), 'The actor shows how many lives can be inhabited within one limited lifetime.', 'The Myth of Sisyphus — Drama', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('f4a4a028-357a-407f-89e3-24e5a01d0d05', (select id from public.guides where slug = 'camus'), 'The conqueror values engaged action while knowing every achievement is temporary.', 'The Myth of Sisyphus — Conquest', array['action', 'purpose', 'clarity', 'perspective', 'presence']::text[], array['stuck', 'unmotivated', 'confused', 'overwhelmed', 'anxious']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('23d54b18-8d74-4092-89ae-3fdb962f8a24', (select id from public.guides where slug = 'camus'), 'Art can describe an absurd condition without pretending to resolve it.', 'The Myth of Sisyphus — Philosophy and Fiction', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('6d06f092-44e8-459f-bdf8-129dc110746f', (select id from public.guides where slug = 'camus'), 'Creation gives form to experience while respecting what remains unexplained.', 'The Myth of Sisyphus — Absurd Creation', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('000ef944-45ca-4066-b26e-8ab682d61fa3', (select id from public.guides where slug = 'camus'), 'Kirilov''s reasoning exposes the danger of turning logical consistency into self-destruction.', 'The Myth of Sisyphus — Kirilov', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('e0fb0990-83c1-463d-a786-313921d58c8b', (select id from public.guides where slug = 'camus'), 'Sisyphus becomes meaningful as an image of consciousness returning to its task.', 'The Myth of Sisyphus — The Myth of Sisyphus', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('ab87b880-3619-4f5a-8352-b13f731930ad', (select id from public.guides where slug = 'camus'), 'Awareness can transform imposed repetition into a consciously carried defiance.', 'The Myth of Sisyphus — The Myth of Sisyphus', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('0af993c7-2ccf-4b8f-8d2c-c7c461d331de', (select id from public.guides where slug = 'camus'), 'Rebellion begins with a refusal that also affirms something worth defending.', 'The Rebel — The Rebel', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('1ee7cc0a-6ed8-4fc8-a5f1-37c13b950599', (select id from public.guides where slug = 'camus'), 'When a limit is crossed, the protest implicitly appeals to a dignity shared with others.', 'The Rebel — The Rebel', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('ec5db1fa-11ca-4e0b-a74e-1f2b4a99734e', (select id from public.guides where slug = 'camus'), 'Genuine rebellion resists humiliation without claiming unlimited permission.', 'The Rebel — The Rebel', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('ccc049ce-2f9f-4840-af77-27e861eecceb', (select id from public.guides where slug = 'camus'), 'Solidarity begins when suffering is recognized as more than a private condition.', 'The Rebel — The Rebel', array['connection', 'support']::text[], array['low', 'insecure']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('31f17b2a-7a68-4a36-91db-fe2021d94b3f', (select id from public.guides where slug = 'camus'), 'Metaphysical rebellion contests an unjust world while remaining attached to life.', 'The Rebel — Metaphysical Rebellion', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('4c14ee9a-d931-4b32-91f2-f0daa770b880', (select id from public.guides where slug = 'camus'), 'Nihilism becomes destructive when denial is allowed to become its only principle.', 'The Rebel — Metaphysical Rebellion', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('0977ed37-d499-4ed7-8371-cccdab643288', (select id from public.guides where slug = 'camus'), 'Revolution betrays rebellion when future justice is used to excuse present cruelty.', 'The Rebel — Historical Rebellion', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('7b5f13d9-bf72-4a3f-82db-2e1b9132cc1e', (select id from public.guides where slug = 'camus'), 'The means used for liberation inevitably shape the freedom that follows.', 'The Rebel — Historical Rebellion', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('b9d9aa0c-e28e-4670-b86b-6f2222df1f1b', (select id from public.guides where slug = 'camus'), 'Historical certainty becomes dangerous when living people are treated as material for an idea.', 'The Rebel — Historical Rebellion', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('dbaae305-6366-4cbc-b137-b65e7a2e3adf', (select id from public.guides where slug = 'camus'), 'Rebellion requires measure: neither submission nor domination can be made absolute.', 'The Rebel — Thought at the Meridian', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('99caf135-2d61-4e3e-b715-5440534a9f1d', (select id from public.guides where slug = 'camus'), 'Art rebels by giving experience form without reducing it to doctrine.', 'The Rebel — Rebellion and Art', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('be63a093-5dd0-4651-b1f1-303015550b44', (select id from public.guides where slug = 'camus'), 'The artist preserves human complexity against systems that demand total agreement.', 'The Rebel — Rebellion and Art', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('ccab89a4-df31-4284-b34d-bbaab9fc746c', (select id from public.guides where slug = 'camus'), 'Justice without freedom becomes oppression; freedom without limits becomes permission for harm.', 'The Rebel — Thought at the Meridian', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('0b2f6eb0-380e-48ec-965c-c0c8bfb86725', (select id from public.guides where slug = 'camus'), 'Balanced thought refuses the false purity promised by political extremes.', 'The Rebel — Thought at the Meridian', array['clarity', 'perspective']::text[], array['confused', 'overwhelmed']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('4ef447d0-5f92-41e3-9609-2919c6da9fa0', (select id from public.guides where slug = 'camus'), 'A rebel accepts responsibility for consequences instead of hiding behind history.', 'The Rebel — Beyond Nihilism', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('a48e82e4-dc49-4b16-b0bb-8876bd27e02c', (select id from public.guides where slug = 'camus'), 'Shared limits make coexistence possible even where agreement is incomplete.', 'The Rebel — Beyond Nihilism', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Rebel', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('da15db94-dfb1-4f89-8566-94ef2c7de1fe', (select id from public.guides where slug = 'camus'), 'Resistance begins by refusing to let force decide what is true or human.', 'Resistance, Rebellion and Death — Letters to a German Friend', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('d482d4e9-3e56-4485-ae9e-f54d09bacec6', (select id from public.guides where slug = 'camus'), 'Love of one''s country need not require hatred of another people.', 'Resistance, Rebellion and Death — Letters to a German Friend', array['forgiveness', 'love', 'support']::text[], array['angry', 'frustrated', 'guilty', 'tired']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('de2f90f3-aec0-45be-a9c7-6a6cbb884bc2', (select id from public.guides where slug = 'camus'), 'A just cause is damaged when it adopts the contempt practiced by its opponent.', 'Resistance, Rebellion and Death — Letters to a German Friend', array['action', 'purpose', 'discipline', 'practice']::text[], array['stuck', 'unmotivated']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('51df32b8-c4b0-4e38-8878-557cef7562cc', (select id from public.guides where slug = 'camus'), 'Courage includes preserving moral limits when circumstances reward cruelty.', 'Resistance, Rebellion and Death — Letters to a German Friend', array['resilience']::text[], array['fearful', 'insecure']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('9eb69506-3883-4108-a11e-0f70a524a038', (select id from public.guides where slug = 'camus'), 'Political realism becomes empty when it forgets the people in whose name it acts.', 'Resistance, Rebellion and Death — Neither Victims nor Executioners', array['action', 'purpose']::text[], array['stuck', 'unmotivated']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('f79e8b45-aaf3-4472-85a4-64719ea75a24', (select id from public.guides where slug = 'camus'), 'Refusing both victimhood and execution is a difficult commitment to human limits.', 'Resistance, Rebellion and Death — Neither Victims nor Executioners', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null)
insert into public.quotes (id, guide_id, text, citation, themes, mood_tags, content_type, source_work, source_url, translator, rights_basis, archived_at)
values
  ('2143dcb5-5f38-4a5e-9724-7e8dd149d25e', (select id from public.guides where slug = 'camus'), 'Conversation remains possible only when no side claims the right to silence every other voice.', 'Resistance, Rebellion and Death — Neither Victims nor Executioners', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('01afc325-6570-4b27-976d-08d50a96b07a', (select id from public.guides where slug = 'camus'), 'Peace requires practical restraint, not merely agreement with peaceful ideals.', 'Resistance, Rebellion and Death — Neither Victims nor Executioners', array['peace', 'action', 'purpose', 'discipline', 'practice']::text[], array['anxious', 'restless', 'stuck', 'unmotivated']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('ac7dbb34-e032-47bd-9af2-55a6c45c8d69', (select id from public.guides where slug = 'camus'), 'The artist serves the present by refusing both isolation and propaganda.', 'Resistance, Rebellion and Death — The Artist and His Time', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('918470a5-3546-48e4-98c6-13526975a527', (select id from public.guides where slug = 'camus'), 'Creation becomes honest when it stays close to ordinary lives and shared suffering.', 'Resistance, Rebellion and Death — The Artist and His Time', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('9600571a-b399-4d9a-81c2-40fc09953808', (select id from public.guides where slug = 'camus'), 'To create dangerously is to accept responsibility without surrendering independence.', 'Resistance, Rebellion and Death — Create Dangerously', array['forgiveness']::text[], array['angry', 'frustrated']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('5279dd63-612a-409d-99be-39fde5d672ec', (select id from public.guides where slug = 'camus'), 'Art matters because it can hold beauty and injustice in view at the same time.', 'Resistance, Rebellion and Death — Create Dangerously', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('9e67f81a-9800-420b-b98f-bbdd7186ca27', (select id from public.guides where slug = 'camus'), 'Capital punishment closes the possibility of correction while claiming certainty about judgment.', 'Resistance, Rebellion and Death — Reflections on the Guillotine', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('201e3bbf-9f94-4d5e-92db-44d274f23a49', (select id from public.guides where slug = 'camus'), 'A society should not teach restraint through an irreversible act of violence.', 'Resistance, Rebellion and Death — Reflections on the Guillotine', array['action', 'purpose', 'discipline', 'practice']::text[], array['stuck', 'unmotivated']::text[], 'source_based_reflection', 'Resistance, Rebellion and Death', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('e8246155-0872-4100-95af-906338fa1a42', (select id from public.guides where slug = 'camus'), 'At Tipasa, attention to sun, sea, stone, and body becomes a form of gratitude.', 'Nuptials — Nuptials at Tipasa', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Nuptials', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('998d8b09-a549-482f-ace2-dad053ab7323', (select id from public.guides where slug = 'camus'), 'Joy can be immediate without pretending that suffering or death do not exist.', 'Nuptials — Nuptials at Tipasa', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Nuptials', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('341055a0-1af1-4134-a3bd-f226b075961f', (select id from public.guides where slug = 'camus'), 'The natural world offers presence, not an argument about what life must mean.', 'Nuptials — Nuptials at Tipasa', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Nuptials', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('4d166c65-98b6-46e5-a151-758686a448fb', (select id from public.guides where slug = 'camus'), 'A life fully felt does not need to be postponed until every question is settled.', 'Nuptials — Nuptials at Tipasa', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Nuptials', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('4ff88408-0128-4d2d-8ef9-c0c5e1908485', (select id from public.guides where slug = 'camus'), 'Algiers reveals a fierce attachment to life lived openly in the body and the weather.', 'Nuptials — Summer in Algiers', array['detachment']::text[], array['discontent', 'restless']::text[], 'source_based_reflection', 'Nuptials', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('1e2897eb-3636-4e9b-8e5f-08130fac6cfb', (select id from public.guides where slug = 'camus'), 'Poverty does not erase beauty, though beauty should never be used to disguise hardship.', 'Nuptials — Summer in Algiers', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'Nuptials', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('919f42ea-4ea4-4e95-840f-b89f8bc4cb8d', (select id from public.guides where slug = 'camus'), 'The desert city invites an honesty stripped of unnecessary decoration.', 'The Myth of Sisyphus and Other Essays — The Minotaur', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus and Other Essays', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('2fb89697-3280-4801-8729-cdf00f10fe60', (select id from public.guides where slug = 'camus'), 'Solitude can clear perception when it is not confused with withdrawal from life.', 'The Myth of Sisyphus and Other Essays — The Minotaur', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus and Other Essays', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('b180da97-629c-4855-8186-7bbcd9a012dc', (select id from public.guides where slug = 'camus'), 'Returning to a beloved place does not restore the past; it tests what remains alive in us.', 'The Myth of Sisyphus and Other Essays — Return to Tipasa', array['love', 'support']::text[], array['guilty', 'tired']::text[], 'source_based_reflection', 'The Myth of Sisyphus and Other Essays', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('4e818fc6-1182-4659-8481-acddf43f2b9b', (select id from public.guides where slug = 'camus'), 'Even after history''s violence, beauty can remain a reason to resist despair.', 'The Myth of Sisyphus and Other Essays — Return to Tipasa', array['resilience']::text[], array['low']::text[], 'source_based_reflection', 'The Myth of Sisyphus and Other Essays', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('baa58231-c427-46fc-ae26-5b08d4b2a6e1', (select id from public.guides where slug = 'camus'), 'Hope becomes credible when it grows beside suffering rather than denying it.', 'The Myth of Sisyphus and Other Essays — Return to Tipasa', array['hope']::text[], array['low', 'tired']::text[], 'source_based_reflection', 'The Myth of Sisyphus and Other Essays', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null),
  ('885bc94d-685d-40e7-b7b7-0c07cad115aa', (select id from public.guides where slug = 'camus'), 'The sea offers no doctrine, yet its nearness can return attention to the living present.', 'The Myth of Sisyphus and Other Essays — The Sea Close By', array['forgiveness', 'presence']::text[], array['angry', 'frustrated', 'anxious', 'overwhelmed']::text[], 'source_based_reflection', 'The Myth of Sisyphus and Other Essays', 'https://www.nobelprize.org/prizes/literature/1957/camus/bibliography/', null, 'Original source-based reflection; no English translation reproduced', null)
